HUD.native_font=(function()
-- Native resource selection; no rectangle glyph renderer.
local M={}
function M.resolve(sr,name,depth)
    local face=HUD.native_font_data.faces[name or 'bigblue']
    local app=sr and sr.Application
    local function available(kind,resource)
        if not app or type(app.can_get)~='function' then return false end
        local ok,value=pcall(app.can_get,kind,resource);return ok and value==true
    end
    if face then
        local material=depth and face.depth or face.clear
        if available('font',face.font) and available('material',material) then return face.font,material,face end
    end
    if name=='hack' and depth and available('font','mods/dbf_hud/fonts/hack_regular_test') and available('material','mods/dbf_hud/materials/hack_regular_test') then
        return 'mods/dbf_hud/fonts/hack_regular_test','mods/dbf_hud/materials/hack_regular_test',face
    end
    local debug='core/performance_hud/debug'
    local material=depth and 'mods/dbf_hud/materials/native_font_depth_loader_control' or debug
    if depth and not available('material',material) then return nil end
    return debug,material,nil
end
return M

end)()
HUD.config=(function()
local M={}
M.fonts={'bigblue','hack','jetbrainsmono','firacode','iosevka'}
M.decorations={'none','outline','brackets','helldivers','double'}
M.colors={'text_color','background_color','heat_white','heat_yellow','heat_red'}
-- Auto clearance in weapon-local metres; independent entries for each view.
-- Resource identity is stable across equip/respawn; never key by entity handle.
M.weapon_clearance={
    ['a8cffb316f0b5c5f']={ -- Autocannon: initial right-shoulder obstruction correction.
        right={x=.12,y=-.08,z=.10},
    },
}
M.defaults={style_3d='standard',fade_3d_unless_aiming=false,show_3d='aiming',keep_hud_upright=false,fp_auto_side='left',placement_mode='auto',decoration='none',debug_logging=false,weapon_screen_test=false,always_show_3d=false,occlusion_mode="gui_depth",hud_occlusion=true,text_color_alpha=255,heat_white_alpha=255,heat_yellow_alpha=255,heat_red_alpha=255,saturation=1.3,left_mount_x=0,left_mount_y=0,left_mount_z=0,fp_mount_x=0,fp_mount_y=0,fp_mount_z=0,scanline_strength=0.18,texture_refresh_hz=0,emissive_intensity=3,world_position_smooth=0.045,world_rotation_smooth=0.08,world_max_lag=0.12,follow=0.65,travel=55,settle=0.22,offset_x=62,offset_y=-5,scale=1,opacity=0.92,
    panel_opacity=0.55,flash_hz=2,frosted=true,pose_marker=false,world_probe=false,anchor_mode='world',weapon_offset_x=62,weapon_offset_y=30,weapon_settle=0.10,weapon_lag=40,mount_x=0,mount_y=0,mount_z=0,text_color='#C4CECA',background_color='#202628',
    heat_white='#E5E7E2',heat_yellow='#E7C85C',heat_red='#E16D65',font='bigblue'}
M.limits={text_color_alpha={0,255},heat_white_alpha={0,255},heat_yellow_alpha={0,255},heat_red_alpha={0,255},saturation={0,2.5},left_mount_x={-2,2},left_mount_y={-2,2},left_mount_z={-2,2},fp_mount_x={-2,2},fp_mount_y={-2,2},fp_mount_z={-2,2},scanline_strength={0,0.6},texture_refresh_hz={0,120},emissive_intensity={0,10},world_position_smooth={0,0.5},world_rotation_smooth={0,0.5},world_max_lag={0,0.5},weapon_offset_x={-1920,1920},weapon_offset_y={-1080,1080},weapon_settle={0.04,1},weapon_lag={0,160},mount_x={-2,2},mount_y={-2,2},mount_z={-2,2},follow={0,1},travel={1,160},settle={0.04,1},offset_x={-1920,1920},offset_y={-1080,1080},
    scale={0.5,2},opacity={0.1,1},panel_opacity={0,1},flash_hz={0.5,3}}
function M.hex(v)
    assert(type(v)=='string','hex color must be a string')
    local h=v:gsub('^#','')
    assert(#h==6 and h:match('^%x+$'),'color needs six hex digits: #RRGGBB')
    return '#'..h:upper()
end
function M.rgb(v)
    v=M.hex(v);return {tonumber(v:sub(2,3),16),tonumber(v:sub(4,5),16),tonumber(v:sub(6,7),16)}
end
function M.new() local t={};for k,v in pairs(M.defaults) do t[k]=v end;return t end
function M.apply(config,values)
    assert(type(values)=='table','configuration must be a table')
    local flattened={}
    for k,v in pairs(values) do
        if M.archived[k] then
            assert(type(v)=='table','archived group must be a table')
            for name,value in pairs(v) do
                assert(M.archived[k][name],'unknown archived setting: '..tostring(name))
                assert(values[name]==nil and flattened[name]==nil,'duplicate setting: '..name)
                flattened[name]=value
            end
        else
            assert(flattened[k]==nil,'duplicate setting: '..tostring(k));flattened[k]=v
        end
    end
    local clean={}
    for k,v in pairs(flattened) do
        assert(M.defaults[k]~=nil,'unknown setting: '..tostring(k))
        local limits=M.limits[k]
        if limits then assert(type(v)=='number' and v==v and v>=limits[1] and v<=limits[2],'invalid setting: '..k)
        elseif (k=='fade_3d_unless_aiming' or k=='keep_hud_upright' or k=='debug_logging' or k=='always_show_3d' or k=='weapon_screen_test' or k=='hud_occlusion' or k=='frosted' or k=='pose_marker' or k=='world_probe') then assert(type(v)=='boolean','setting must be boolean')
        elseif k=='style_3d' then assert(v=='standard' or v=='hologram','invalid 3D style')
        elseif k=='show_3d' then assert(v=='occluded' or v=='always' or v=='aiming','invalid 3D visibility')
        elseif k=='occlusion_mode' then assert(v=='mesh' or v=='gui' or v=='gui_depth','invalid occlusion mode')
        elseif k=='fp_auto_side' then assert(v=='left' or v=='right','invalid first-person side')
        elseif k=='placement_mode' then assert(v=='manual' or v=='auto','invalid placement mode')
        elseif k=='anchor_mode' then assert(v=='weapon' or v=='crosshair' or v=='world','invalid anchor mode')
        elseif k=='decoration' then local found=false;for _,name in ipairs(M.decorations) do if v==name then found=true end end;assert(found,'unknown decoration')
        elseif k=='font' then assert(v=='debug' or HUD.native_font_data.faces[v],'unknown HUD font')
        else v=M.hex(v) end
        clean[k]=v
    end
    if clean.hud_occlusion~=nil and clean.occlusion_mode==nil then clean.occlusion_mode=clean.hud_occlusion and 'gui_depth' or 'gui' end
    -- Migrate retired mesh selection to the verified direct WorldGUI path.
    if clean.occlusion_mode=='mesh' then clean.occlusion_mode='gui_depth' end
    if clean.show_3d==nil and clean.always_show_3d~=nil then clean.show_3d=clean.always_show_3d and 'always' or 'occluded' end
    if clean.show_3d then clean.always_show_3d=clean.show_3d=='always' end
    if clean.always_show_3d~=nil then clean.occlusion_mode=clean.always_show_3d and 'gui' or 'gui_depth' end
    if clean.occlusion_mode then clean.hud_occlusion=clean.occlusion_mode~='gui';clean.always_show_3d=clean.occlusion_mode=='gui' end
    for k,v in pairs(clean) do config[k]=v end
end
M.archived={archived_mesh={weapon_screen_test=true,saturation=true,scanline_strength=true,texture_refresh_hz=true,emissive_intensity=true},research={pose_marker=true,world_probe=true}}
function M.serialize(config)
    local keys={};local archived={}
    for _,group in pairs(M.archived) do for k in pairs(group) do archived[k]=true end end
    for k in pairs(M.defaults) do if not archived[k] and k~='occlusion_mode' and k~='hud_occlusion' and k~='show_3d' and k~='always_show_3d' and k~='placement_mode' and not k:match('^left_mount_') and not k:match('^fp_mount_') and not k:match('^mount_') then keys[#keys+1]=k end end
    table.sort(keys)
    local out={'-- DBF-HUD tuning. Active settings below; camera placement is unchanged.','return {','    -- Active display, palette, placement and diagnostics.'}
    local function value(v)return type(v)=='string' and string.format('%q',v) or tostring(v)end
    for _,k in ipairs(keys) do out[#out+1]='    '..k..' = '..value(config[k])..',' end
    for _,name in ipairs({'archived_mesh','research'}) do
        out[#out+1]='    -- Retained settings; mesh is disabled. Research markers require debug_logging.'
        out[#out+1]='    '..name..' = {'
        local members={};for k in pairs(M.archived[name]) do members[#members+1]=k end;table.sort(members)
        for _,k in ipairs(members) do out[#out+1]='        '..k..' = '..value(config[k])..',' end
        out[#out+1]='    },'
    end
    out[#out+1]='}';return table.concat(out,'\n')..'\n'
end

return M

end)()
HUD.font=(function()
-- Native text bounds; no rectangle glyph renderer.
local M={}
function M.supported(name)return HUD.native_font_data.faces[name or 'bigblue']~=nil end
function M.measure(text,size,name,continuous)
    local face=HUD.native_font_data.faces[name or 'bigblue']
    local sr=rawget(_G,'stingray')
    if sr and HUD.native_font then local f,m,active=HUD.native_font.resolve(sr,name,false);face=active end
    if not face then return 0,-size*.2,#text*size*.6,size*.8 end
    local factor=size/face.em;local left,bottom,right,top,offset=0,0,0,0,0
    for i=1,#text do
        local g=face.glyphs[text:byte(i)] or face.glyphs[63]
        left=math.min(left,offset+g[2]);bottom=math.min(bottom,g[3])
        right=math.max(right,offset+g[4]);top=math.max(top,g[5]);offset=offset+g[1]
    end
    return left*factor,bottom*factor,right*factor,top*factor
end
return M

end)()
HUD.motion=(function()
-- Exact critically damped spring; all coordinates are 1080p reference pixels.
local M = {}
local function finite(x) return type(x)=='number' and x==x and math.abs(x)<1e8 end
function M.new() return {x=0,y=0,vx=0,vy=0,ready=false} end
function M.axis(x,v,target,dt,omega)
    local delta=x-target
    local j=v+omega*delta
    local e=math.exp(-omega*dt)
    return target+(delta+j*dt)*e,(v-omega*j*dt)*e
end
function M.step(s, target, dt, cfg)
    local x,y=0,0
    if target and finite(target.x) and finite(target.y) then
        x,y=target.x*cfg.follow,target.y*cfg.follow
    end
    local radius=math.sqrt(x*x+y*y)
    if radius>cfg.travel then x,y=x*cfg.travel/radius,y*cfg.travel/radius end
    if not finite(dt) or dt<0 then dt=0 end
    if not s.ready or dt>0.35 then s.x,s.y,s.vx,s.vy=x,y,0,0; s.ready=true end
    local omega=4.75/math.max(0.04,cfg.settle)
    s.x,s.vx=M.axis(s.x,s.vx,x,dt,omega)
    s.y,s.vy=M.axis(s.y,s.vy,y,dt,omega)
    -- Moving targets can retain momentum; enforce the hard travel envelope too.
    radius=math.sqrt(s.x*s.x+s.y*s.y)
    if radius>cfg.travel then
        s.x,s.y=s.x*cfg.travel/radius,s.y*cfg.travel/radius
        local outward=(s.vx*s.x+s.vy*s.y)/(cfg.travel*cfg.travel)
        if outward>0 then s.vx,s.vy=s.vx-outward*s.x,s.vy-outward*s.y end
    end
    return s.x,s.y
end
-- Limit lag relative to the moving weapon, never relative to screen center.
function M.attach(s,target,dt,cfg)
    if not finite(dt) or dt<0 then dt=0 end
    if not s.ready or dt>.35 then s.x,s.y,s.vx,s.vy=target.x,target.y,0,0;s.ready=true end
    local omega=4.75/cfg.weapon_settle
    s.x,s.vx=M.axis(s.x,s.vx,target.x,dt,omega)
    s.y,s.vy=M.axis(s.y,s.vy,target.y,dt,omega)
    local dx,dy=s.x-target.x,s.y-target.y;local d=math.sqrt(dx*dx+dy*dy)
    if d>cfg.weapon_lag then
        s.x,s.y=target.x+dx*cfg.weapon_lag/d,target.y+dy*cfg.weapon_lag/d
        s.vx,s.vy=0,0
    end
    return s.x,s.y
end
return M

end)()
