}

end)()
HUD.layout=(function()
-- Renderer-independent HUD; geometry uses bottom-left coordinates.
local M={}
function M.heat_color(fraction,clock,cfg)
    if fraction>=0.95 then return math.floor((clock or 0)*cfg.flash_hz*2)%2==0 and cfg.heat_red or cfg.heat_yellow end
    if fraction>=0.86 then return cfg.heat_red end
    if fraction>=0.75 then return cfg.heat_yellow end
    return cfg.heat_white
end
function M.decorate(out,frame,scale,cfg,opacity)
    local left,bottom=frame.x,frame.y
    local right,top=left+frame.w,bottom+frame.h
    -- Decorations stay inside the measured panel perimeter, including at screen edges.
    -- Shared rectangle commands preserve direct WorldGUI depth and all screen renderers.
    local style=cfg.decoration or 'none'
    local w,h=right-left,top-bottom;local line=scale
    local neutral=HUD.config.rgb(cfg.text_color)
    local yellow=HUD.config.rgb(cfg.heat_yellow)
    local function border(dx,dy,bw,bh,color,strength)
        out[#out+1]={type='rect',decoration=true,x=left+dx,y=bottom+dy,w=bw,h=bh,
            c=color or neutral,a=opacity*(cfg.text_color_alpha or 255)/255*(strength or .7)}
    end
    local function outline(inset,strength)
        border(inset,inset,w-2*inset,line,nil,strength)
        border(inset,h-inset-line,w-2*inset,line,nil,strength)
        border(inset,inset,line,h-2*inset,nil,strength)
        border(w-inset-line,inset,line,h-2*inset,nil,strength)
    end
    local length=math.min(12*scale,w/4,h/4)
    if style=='outline' then outline(0,.55)
    elseif style=='brackets' then
        for _,cx in ipairs({0,w-length}) do for _,cy in ipairs({0,h-line}) do border(cx,cy,length,line) end end
        for _,cx in ipairs({0,w-line}) do for _,cy in ipairs({0,h-length}) do border(cx,cy,line,length) end end
    elseif style=='helldivers' then
        -- Native HUD-inspired open rails, pale angular corners and yellow highlights.
        border(0,0,line,h,nil,.35);border(w-line,0,line,h,nil,.35)
        border(0,0,length,line,nil,.9);border(0,h-line,length,line,nil,.9)
        border(w-length,0,length,line,nil,.9);border(w-length,h-line,length,line,nil,.9)
        border(0,0,line,length,nil,.9);border(w-line,h-length,line,length,nil,.9)
        border(0,h-2*line,length,2*line,yellow,.9)
        border(w-length,0,length,2*line,yellow,.9)
    elseif style=='double' then outline(0,.65);outline(3*scale,.25) end
end
function M.compose(m,x,y,scale,opacity,cfg,clock,measure)
    cfg=cfg or HUD.config.defaults
    local pixel=HUD.font.supported(cfg.font)
    if pixel and not measure then measure=function(text,size)return HUD.font.measure(text,size,cfg.font)end end
    local d={};local heat=m.kind=='heat'
    local vent=heat and m.state=='VENT'
    if vent then opacity=opacity*(0.25+0.75*(0.5+0.5*math.cos((clock or 0)*math.pi*4))) end
    local heat_ink=vent and cfg.heat_red or M.heat_color(m.fraction or 0,clock,cfg)
    local key='text_color'
    if heat then
        if vent then key='heat_red'
        elseif m.fraction>=.95 then key=math.floor((clock or 0)*cfg.flash_hz*2)%2==0 and 'heat_red' or 'heat_yellow'
        elseif m.fraction>=.86 then key='heat_red'
        elseif m.fraction>=.75 then key='heat_yellow'
        else key='heat_white' end
    elseif m.warning then key=m.value==0 and 'heat_red' or 'heat_yellow' end
    local ink=HUD.config.rgb(cfg[key])
    local ink_alpha=(cfg[key..'_alpha'] or 255)/255
    local function rect(dx,dy,w,h,c,a,kind)
        d[#d+1]={type=kind or 'rect',x=x+dx*scale,y=y+dy*scale,w=w*scale,h=h*scale,c=c,a=(a or 1)*opacity*ink_alpha,frosted=cfg.frosted}
    end
    local function text(t,dx,dy,size,c,a)
        if pixel then size=t=='%' and 24 or (size>=20 and 36 or 12) end
        local reminder=m.reload_reminder and size>=20 and (0.35+0.65*(0.5+0.5*math.cos((clock or 0)*math.pi*2*cfg.flash_hz))) or 1
        d[#d+1]={type='text',text=tostring(t),font=cfg.font,x=x+dx*scale,y=y+dy*scale,size=size*scale,c=c,a=(pixel and 1 or (a or 1))*opacity*ink_alpha*reminder}
    end
    local number=type(m.value)=='number' and string.format('%02d',m.value) or m.value
    local number_top,label_top=0,0
    if pixel then
        local a,b,c,nt=measure(number,36*scale)
        local e,f,g,lt=measure('HEAT SINKS',12*scale)
        number_top=nt/scale;label_top=lt/scale
    end
    if heat then
        text('HEAT',0,pixel and math.max(42,5+number_top+3) or 42,10,ink,.85)
        text(number..'%',0,5,32,ink)
        for i=0,19 do
            local fill=math.max(0,math.min(1,m.fraction*20-i))
            rect(i*5,-3,3.5,3,ink,.12)
            if fill>0 then rect(i*5,-3,3.5*fill,3,ink,.95) end
        end
        local footer=m.fraction>=.95 and 'OVERHEAT' or (m.state=='VENT' and 'VENT' or
            (m.reserve and string.format('%02d SINKS',m.reserve) or '-- SINKS'))
        text(footer,0,pixel and math.min(-19,-7-label_top) or -19,9,ink,.9)
    else
        local heading=(m.ammo_mode=='APHET' or m.ammo_mode=='FLAK') and m.ammo_mode or m.label
        local heading_y=pixel and math.max(42,5+number_top+3) or 42
        text(heading..(m.chamber_bonus==1 and ' +1' or ''),0,heading_y,8,ink,0.72)
        if m.ammo_mode=='APHET' or m.ammo_mode=='FLAK' then d[#d].size=(pixel and 18 or 12)*scale end
        text(number,0,5,32,ink)
        local fire_icon=HUD.fire_icons[m.energy_icon or m.fire_mode]
        if fire_icon and not m.ammo_mode then
            d[#d].mode_count=true
            local edge=#number*(pixel and 36 or 32)*.6
            if measure then local a,b,c=measure(number,(pixel and 36 or 32)*scale);if c then edge=c/scale end end
            -- Fit both dimensions: wide single/burst icons must not be
            -- enlarged merely to match the square auto icon's height.
            local factor=24/math.max(fire_icon.w,fire_icon.h)
            local bottom,top=0,32
            if measure then local a,b,c,e=measure(number,(pixel and 36 or 32)*scale);if e then bottom,top=b/scale,e/scale end end
            if m.fire_mode=='AUTO' then
                factor=(top-bottom)/fire_icon.h
            end
            local icon_y=5+(bottom+top-fire_icon.h*factor)/2
            for _,run in ipairs(fire_icon.runs) do
                rect(edge+8+run[1]*factor,icon_y+run[2]*factor,run[3]*factor,run[4]*factor,ink,.9)
                d[#d].mode_icon=true
            end
        end
        if m.ammo_mode=='APHET' or m.ammo_mode=='FLAK' then d[#d].mode_count=true end
        if m.ammo_mode=='APHET' or m.ammo_mode=='FLAK' then
            local edge=#number*(pixel and 36 or 32)*.6
            if measure then local a,b,c=measure(number,(pixel and 36 or 32)*scale);if c then edge=c/scale end end
            local ix,iy=edge+8,5
            -- Large pictogram shares the main count row.
            local function mode_rect(dx,dy,w,h)
                rect(ix+dx*1.8,iy+dy*1.8,w*1.8,h*1.8,ink,.9)
                d[#d].mode_icon=true
            end
            -- Compact cartridge / airburst pictograms use the same depth-aware
            -- primitives as the HUD; native icon materials are not depth-validated.
            if m.ammo_mode=='APHET' then
                mode_rect(5,0,6,12);mode_rect(6,12,4,3);mode_rect(7,15,2,2)
                mode_rect(4,0,8,2)
            else
                mode_rect(6,6,4,4)
                for _,p in ipairs({{7,13},{7,0},{0,7},{13,7},{2,2},{12,12},{2,12},{12,2}}) do
                    mode_rect(p[1],p[2],2,2)
                end
            end
        end
        if m.suffix then
            local edge=60
            if pixel then local a,b,c=measure(number,36*scale);edge=c/scale end
            text(m.suffix,edge+4,11,12,ink,0.7)
        end
        for i=0,11 do rect(i*6.5,-3,4.5,3,ink,m.fraction and i/12<m.fraction and 0.92 or 0.14) end
        local reserve=m.reserve and (string.format('%02d',m.reserve)..' '..(m.reserve_kind or 'RES')) or '-- RES'
        local footer=m.state~='READY' and m.state or reserve
        text(footer,0,pixel and math.min(-19,-7-label_top) or -19,9,ink,0.8)
    end
    if heat then
        local icon=HUD.fire_icons[m.energy_icon or m.fire_mode]
        if icon then
            local command
            for _,v in ipairs(d) do if v.type=='text' and v.text==number..'%' then command=v end end
            command.mode_count=true
            local a,b,e,f=0,0,#command.text*command.size*.6,command.size
            if measure then a,b,e,f=measure(command.text,command.size) end
            local factor=24/math.max(icon.w,icon.h)
            local iy=5+(b/scale+f/scale-icon.h*factor)/2
            for _,run in ipairs(icon.runs) do
                rect(e/scale+8+run[1]*factor,iy+run[2]*factor,run[3]*factor,run[4]*factor,ink,.9)
                d[#d].mode_icon=true
            end
        end
    end
    -- Measure content first. Frame, frost and accents share these same bounds.
    local left,bottom,right,top=math.huge,math.huge,-math.huge,-math.huge
    for _,c in ipairs(d) do
        local x0,y0,x1,y1=c.x,c.y,c.x+(c.w or 0),c.y+(c.h or 0)
        if c.type=='text' then
            local a,b,e,f
            if measure then a,b,e,f=measure(c.text,c.size) end
            if not e then a,b,e,f=0,-c.size*.2,#c.text*c.size*.6,c.size*.8 end
            x0,y0,x1,y1=c.x+a,c.y+b,c.x+e,c.y+f
        end
        left,bottom,right,top=math.min(left,x0),math.min(bottom,y0),math.max(right,x1),math.max(top,y1)
    end
    local pad=8*scale
    left,bottom,right,top=left-pad,bottom-pad,right+pad,top+pad
    do
        local center=(left+right)/2
        local bar_left,bar_right=math.huge,-math.huge
        for _,v in ipairs(d) do if v.type=='rect' and not v.mode_icon then bar_left=math.min(bar_left,v.x);bar_right=math.max(bar_right,v.x+v.w) end end
        for _,c in ipairs(d) do
            if c.type=='text' then
                c.center_in_frame=true
                local a,b,e,f
                if measure then a,b,e,f=measure(c.text,c.size) end
                if not e then a,e=0,#c.text*c.size*.6 end
                c.x=center-(a+e)/2
            elseif c.type=='rect' and not c.mode_icon then
                c.center_bar=true
                -- Ammo bar retains its own cell spacing, centered as a group.
                c.x=c.x+center-(bar_left+bar_right)/2
            end
        end
    end
    local icon_right,icon_top=-math.huge,-math.huge
    for _,c in ipairs(d) do
        if c.mode_icon then icon_right=math.max(icon_right,c.x+c.w);icon_top=math.max(icon_top,c.y+c.h) end
    end
    if icon_right>-math.huge then
        local dx,dy=right-pad-icon_right,0
        for _,c in ipairs(d) do if c.mode_icon then c.x=c.x+dx;c.y=c.y+dy end end
    end
    local heading_command;local icon_left,icon_edge=math.huge,-math.huge
    for _,c in ipairs(d) do
        if c.mode_count then heading_command=c end
        if c.mode_icon then icon_left=math.min(icon_left,c.x);icon_edge=math.max(icon_edge,c.x+c.w) end
    end
    if heading_command and icon_left<math.huge then
        local h=heading_command;local a,b,e,f
        if measure then a,b,e,f=measure(h.text,h.size) end
        if not e then a,e=0,#h.text*h.size*.6 end
        local gap=8*scale;local width=e-a+gap+icon_edge-icon_left
        local start=(left+right-width)/2
        h.x=start-a
        local shift=start+e-a+gap-icon_left
        for _,c in ipairs(d) do if c.mode_icon then c.x=c.x+shift end end
    end
    local out={{type='panel',x=left,y=bottom,w=right-left,h=top-bottom,
        c=HUD.config.rgb(cfg.background_color),a=cfg.panel_opacity*opacity,frost_a=opacity,frosted=cfg.frosted}}
    for _,c in ipairs(d) do out[#out+1]=c end
    M.decorate(out,out[1],scale,cfg,opacity)
    if m.fire_mode=='AUTO' or m.fire_mode=='SEMI' or m.fire_mode=='BURST' or m.fire_mode=='ALT' then
        local size=(pixel and 12 or 8)*scale
        local a,b,e,f
        if measure then a,b,e,f=measure(m.fire_mode,size) end
        if not e then a,b,e,f=0,-size*.2,#m.fire_mode*size*.6,size*.8 end
        local cw,ch=right-left,f-b+8*scale
        local child={type='panel',child=true,x=(left+right-cw)/2,y=bottom-2*scale-ch,w=cw,h=ch,
            c=HUD.config.rgb(cfg.background_color),a=cfg.panel_opacity*opacity,frost_a=opacity,frosted=cfg.frosted}
        local group={child,{type='text',child=true,text=m.fire_mode,font=cfg.font,
            x=child.x+cw/2-(a+e)/2,y=child.y+4*scale-b,size=size,c=ink,a=opacity*ink_alpha}}
        M.decorate(group,child,scale,cfg,opacity)
        for _,command in ipairs(group) do command.child=true;out[#out+1]=command end
    end
    return out
end
return M

end)()
HUD.memory=(function()
-- Private FFI symbols prevent collisions with other addons' declarations.
local M={}
function M.native()
    local ffi=require('ffi')
    pcall(ffi.cdef, [[
    void *dbf_hud_module(const char*) __asm__("GetModuleHandleA");
    void *dbf_hud_process(void) __asm__("GetCurrentProcess");
    int dbf_hud_read(void*,const void*,void*,size_t,size_t*) __asm__("ReadProcessMemory");
    unsigned long dbf_hud_filename(void*,char*,unsigned long) __asm__("GetModuleFileNameA");
    ]])
    local k=ffi.load('kernel32'); local process=k.dbf_hud_process()
    local buffer=ffi.new('uint8_t[4096]');local got=ffi.new('size_t[1]')
    local file,log_size;local log_attempted=false
    local backend={
        module=function(name) local p=k.dbf_hud_module(name); if p~=nil then return tonumber(ffi.cast('uintptr_t',p)) end end,
        read=function(address,size)
            if address<65536 or address+size>=2^47 or size<1 or size>4096 then return nil end
            got[0]=0
            if k.dbf_hud_read(process,ffi.cast('const void*',address),buffer,size,got)==0 or tonumber(got[0])~=size then return nil end
            return ffi.string(buffer,size)
        end
    }
    function backend.log(line)
        if not log_attempted then
            log_attempted=true
            local buf=ffi.new('char[4096]');local n=tonumber(k.dbf_hud_filename(nil,buf,4096))
            if n and n>0 and n<4096 then
                local exe=ffi.string(buf,n):gsub('\\','/')
                local root=exe:match('^(.*)/[Bb][Ii][Nn]/[^/]+$')
                if root then backend.log_path=root..'/DBF-HUD.log';file=io.open(backend.log_path,'w') end
            end
            log_size=0
        end
        if file and log_size<512*1024 then
            file:write(line..'\n');file:flush();log_size=log_size+#line+1
        end
    end
    local function tuning_path()
        local buf=ffi.new('char[4096]');local n=tonumber(k.dbf_hud_filename(nil,buf,4096))
        assert(n>0 and n<4096,'executable path unavailable')
        local root=ffi.string(buf,n):gsub('\\','/'):match('^(.*)/[Bb][Ii][Nn]/[^/]+$')
        assert(root,'game installation root unavailable')
        return root..'/DBF-HUD-tuning.lua'
    end
    function backend.camera_log_path() return tuning_path():gsub('DBF%-HUD%-tuning.lua$','DBF-HUD-camera.log') end
    function backend.camera_request()
        local path=tuning_path():gsub('DBF%-HUD%-tuning.lua$','DBF-HUD-camera-request.txt')
        local file=io.open(path,'r');if not file then return nil end
        local label=file:read(65);file:close();assert(os.remove(path),'camera request acknowledgement failed')
        assert(#label<=64 and label:match('^[%w_%-]+%s*$'),'invalid camera snapshot label')
        return label:match('^[%w_%-]+')
    end
    function backend.read_tuning()
        local path=tuning_path();local f=io.open(path,'r')
        -- Compatibility: old settings are readable; writes use the new filename.
        if not f then path=path:gsub('DBF%-HUD%-tuning.lua$','AstraAmmo-tuning.lua');f=io.open(path,'r') end
        if not f then return nil end
        local body=f:read(65537);f:close();assert(#body<=65536,'tuning file too large')
        local chunk=assert(loadstring(body,'@'..path));setfenv(chunk,{})
        local values=chunk();assert(type(values)=='table','tuning file must return a table')
        return values
    end
    function backend.read_weapon_offsets()
        local path=tuning_path():gsub('DBF%-HUD%-tuning.lua$','DBF-HUD-weapon-offsets.lua')
        local f=io.open(path,'r');if not f then return nil end
        local body=f:read(65537);f:close();assert(#body<=65536,'weapon offsets file too large')
        local chunk=assert(loadstring(body,'@'..path));setfenv(chunk,{})
        return chunk()
    end
    function backend.write_tuning(body)
        local path=tuning_path();local tmp=path..'.tmp'
        local f=assert(io.open(tmp,'w'));local ok,err=f:write(body);local closed,cerr=f:close()
        assert(ok and closed,err or cerr)
        -- Windows rename cannot replace an existing file; keep a recoverable backup.
        local previous=io.open(path,'r')
        if previous then previous:close();os.remove(path..'.bak');assert(os.rename(path,path..'.bak')) end
        local moved,why=os.rename(tmp,path)
        if not moved then os.rename(path..'.bak',path);error(why) end
        return path
    end
    function backend.close() if file then file:close();file=nil end end
    return backend
end
function M.new(backend)
    local r={reads=0,bytes=0}
    function r.reset() r.reads,r.bytes=0,0 end
    function r.read(a,n)
        assert(type(a)=='number' and a==a and a%1==0 and a>=65536 and a+n<2^47,'invalid address')
        assert(n>0 and n<=4096,'invalid read size')
        r.reads,r.bytes=r.reads+1,r.bytes+n
        assert(r.reads<=512 and r.bytes<=65536,'read budget exceeded')
        local s=backend.read(a,n); assert(s and #s==n,'unreadable memory');return s
    end
    function r.u(s,o)
        local a,b,c,d=s:byte(o+1,o+4);assert(d,'short uint32');return a+b*256+c*65536+d*16777216
    end
    function r.i(s,o) local v=r.u(s,o);return v>=2^31 and v-2^32 or v end
    function r.f(s,o)
        local v=r.u(s,o);local sign=v>=2^31 and -1 or 1
        local e=math.floor(v/2^23)%256;local m=v%2^23
        assert(e~=255,'nonfinite float')
        return sign*(e==0 and m*2^-149 or (1+m/2^23)*2^(e-127))
    end
    function r.p(a)
        local s=r.read(a,8);local p=r.u(s,0)+r.u(s,4)*2^32
        assert(p>=65536 and p<2^47,'invalid pointer');return p
    end
    function r.map(a,key,limit)
        local h=r.read(a,20);local n,empty,mult=r.u(h,8),r.u(h,12),r.u(h,16)
        if n==0 or key==empty or key==0xffffffff then return nil end
        assert(n<=limit and n>0,'invalid map capacity')
        local pow=n;while pow>1 and pow%2==0 do pow=pow/2 end
        assert(pow==1,'invalid map capacity')
        local p=r.p(a)
        -- Split multiplication keeps the low 32 bits exact under Lua doubles.
        local start=((key%65536)*(mult%65536)+((math.floor(key/65536)*(mult%65536)+(key%65536)*math.floor(mult/65536))%65536)*65536)%2^32
        for probe=0,math.min(n,128)-1 do
            local row=r.read(p+((start+probe)%n)*8,8);local k=r.u(row,0)
            if k==empty then return nil end
            if k==key then local index=r.u(row,4);if index~=0xffffffff then return index end;return nil end
        end
        error('map probe limit')
    end
    return r
end
return M

end)()
HUD.layouts=(function()
-- Reference facts: Reticle Ammo HUD 1.1.0, Steam 25327279 and September 24 PE.
-- No layout is guessed on unknown builds. Offsets relative to game.dll.
return {
    stamps={[0x6AA96B14]=0x4770000,[0x6AB3B43F]=0x4744000},
    player=0x3326468,owner=0x346BF98,inventory=0x3326738,driver=0x3326660,
    selector=0x3326420,magazine=0x3326648,rounds=0x3326CF0,heat=0x3326D48,
    entity_map=0xF1AEB0,unit_map=0xF22EC8,records=0xF32F18,
    deposit={0x33265F0,0x33265E8},resource={0x3326AA0,0x3326AA8,0x3326A98,0x3326AB0},
    static={magazine={0xF124A0,540,160},rounds={0xF12820,50,0x88},heat={0xF12CC8,58,0x250},weapon_data={0xF12BD8,730,0x4d0,0x70,0xb0}},
    signatures={
        {0x607200,'488b0561f2d10283b88400000000'},
        {0x6066ed,'8b9410a8030000'},
        {0xfd9c93,'4c8b15fe224902'},
        {0xfd9cc5,'498b9ac82ef200'},
        {0xfd9d83,'498b9ab0aef100'},
        {0x9a83e0,'4c8b1551e39702'},
        {0x745db6,'488b1da308be02'},
        {0x744dc2,'4c8b0d271fbe02'},
        {0x744d02,'488b2d3f19be02'},
        {0x764efa,'4c8b15471ebc02'},
        {0x764f79,'8bc8498b4258488d1449807c9008000f94c0'}
    }
}

end)()
HUD.reader=(function()
local Memory,Layout=HUD.memory,HUD.layouts
local M={}
local function flag(v,b) return math.floor(v/b)%2==1 end
local function valid(v,limit) return v>=0 and v<=limit end
function M.new(backend)
    local r=Memory.new(backend);local base;local checked=false
    local self={status='starting'}
    local function global(name) return r.p(base+Layout[name]) end
    local function component(m,map,registry,id,record)
        local index=r.map(m+map,id,65536)
        if not index then return nil end
        assert(index<4096,'component index')
        assert(r.read(r.p(r.p(m+registry)+index*8),24)==record,'component identity')
        return index
    end
    local function entity(owner,id)
        if not id or id==0 or id==0xffffffff then return nil end
        local index=r.map(owner+Layout.entity_map,id,1048576)
        if not index then return nil end
        assert(index<1048576,'entity index')
        local rec=r.read(owner+Layout.records+index*24,24)
        assert(r.u(rec,8)==id,'entity identity');return rec,owner+Layout.records+index*24
    end
    local function config(kind,m,id,rec,owner)
        local spec=Layout.static[kind]
        if kind~='magazine' then
            local i=r.map(m+(spec[4] or 0x68),id,65536)
            if i then assert(i<4096,'override index');return r.read(r.p(m+(spec[5] or 0xa8))+i*spec[3],spec[3]) end
        end
        local p=r.p(owner+spec[1]);local n=spec[2];local key=rec:sub(1,8)
        local home=((r.u(rec,4)%n)*(2^32%n)+r.u(rec,0)%n)%n
        for probe=0,math.min(n,128)-1 do
            local row=r.read(p+((home+probe)%n)*16,16)
            if row:sub(1,8)==string.rep('\0',8) then return nil end
            if row:sub(1,8)==key then
                local i=r.u(row,8);assert(i<n and r.u(row,12)==0,'config index')
                return r.read(p+n*16+i*spec[3],spec[3])
            end
        end
        return nil
    end
    local function deposit(owner,id)
        local rec=entity(owner,id);if not rec then return nil end
        for _,off in ipairs(Layout.deposit) do
            local ok,v=pcall(function()
                local m=r.p(base+off);local i=component(m,0x20,0x38,id,rec)
                if not i then return nil end
                local c=r.i(r.read(r.p(m+0x50)+i*8,8),0)
                if valid(c,5000) then return c end
            end)
            if ok and v then return v end
        end
    end
    function self.validate()
        r.reset();base=backend.module('game.dll');assert(base,'game.dll not loaded')
        local dos=r.read(base,64);assert(dos:sub(1,2)=='MZ','DOS signature')
        local pe=r.u(dos,0x3c);assert(pe<0x100000,'PE offset')
        local header=r.read(base+pe,0x80)
        assert(header:sub(1,4)=='PE\0\0','PE signature')
        assert(Layout.stamps[r.u(header,8)]==r.u(header,0x50),'unsupported game build')
        for _,s in ipairs(Layout.signatures) do
            local bytes=s[2]:gsub('..',function(h) return string.char(tonumber(h,16)) end)
            assert(r.read(base+s[1],#bytes)==bytes,'layout signature mismatch')
        end
        checked=true;self.status='validated'
    end
    function self.snapshot()
        if not checked then self.validate() end
        r.reset()
        local pm=global('player');local n=r.read(pm+0x84,8)
        if r.u(n,0)==0 or r.u(n,4)==0 then return nil,'no local player' end
        local pl=r.read(r.p(pm+0xe8),24)
        assert(flag(pl:byte(21),1) and r.map(pm+0xd0,r.u(pl,8),64)==0,'local ownership')
        local unit=r.u(r.read(pm+0x3a8,4),0)
        if unit==0x7fff then return nil,'no avatar' end
        local owner=global('owner');local ai=r.map(owner+Layout.unit_map,unit,1048576)
        if not ai then return nil,'no avatar entity' end
        assert(ai<1048576,'avatar index')
        local avatar=r.read(owner+Layout.records+ai*24,24);local aid=r.u(avatar,8)
        assert(r.u(avatar,16)==unit and flag(avatar:byte(21),1),'avatar identity')
        local inv=global('inventory');local ii=component(inv,0x28,0x40,aid,avatar)
        if not ii then return nil,'no inventory' end
        assert(ii<r.u(r.read(inv+0x14,4),0),'inventory index')
        local inventory=r.read(r.p(inv+0x50)+ii*48,48);local slot=r.u(inventory,28)
        local offset=({[1]=0,[2]=4,[3]=8,[4]=16,[5]=16,[6]=12})[slot]
        local wid=offset and r.u(inventory,offset);local inventory_weapon=wid
        local lowered=false;local mounted=false
        local sm=global('selector');local si=r.map(sm+0x30,aid,1048576)
        if si then
            local live=r.u(r.read(sm+0x18,4),0);local cap=r.u(r.read(sm+0x10,4),0)
            assert(live<=cap and live<=262144 and si<live,'selector bounds')
            assert(r.read(r.p(r.p(sm+0x48)+si*8),24)==avatar,'selector identity')
            local at=r.p(sm+0x60)+si*0x1d0;local selected=r.u(r.read(at,4),0)
            -- Selector interpolation rates are NOT a reliable movement visibility signal.
            if selected~=0 and selected~=0xffffffff and selected~=aid then
                wid=selected;mounted=wid~=inventory_weapon
            end
        end
        local rec,record_address=entity(owner,wid);if not rec then return nil,'no selected weapon' end
        -- The machine gun uses the identity-checked magazine path below. Its
        -- inherited exclusion was removed after bounded live component checks.
        assert(mounted or flag(rec:byte(21),1),'weapon ownership')
        local main_rec,main_wid,main_address=rec,wid,record_address
        local control_address,active_mode
        local control_ok,address,mode=pcall(function()
            assert(r.read(base+0x75673a,7)==string.char(0x4c,0x8b,0x15,0x9f,0x05,0xbd,0x02),'weapon control getter binding')
            local control_manager=r.p(base+0x3326ce0)
            local control_index=component(control_manager,0x30,0x48,wid,rec)
            if not control_index then return nil end
            local count=r.u(r.read(control_manager+0x20,4),0)
            assert(count<=4096 and control_index<count,'weapon control bounds')
            local at=r.p(control_manager+0x60)+control_index*12
            return at,r.u(r.read(at,4),0)
        end)
        if control_ok then control_address,active_mode=address,mode end
        if active_mode==8 then
            local auxiliary=r.p(base+0x3326a38)
            local index=r.map(auxiliary+0x278,wid,4096)
            if not index or index>=4096 or not si then return nil,'alternate ammunition unavailable' end
            local state=r.read(r.p(auxiliary+0x2a0)+index*128,128)
            local ammo_id=r.u(state,0x64)
            local selector=r.read(r.p(sm+0x60)+si*0x1d0,5*0x50)
            local attached=false
            for slot=0,4 do
                if r.u(selector,slot*0x50)==wid and r.u(selector,slot*0x50+4)==ammo_id then attached=true end
            end
            if not attached then return nil,'alternate weapon attachment mismatch' end
            local ammo_rec,ammo_address=entity(owner,ammo_id)
            if not ammo_rec then return nil,'alternate weapon missing' end
            local owner_manager=r.p(base+0x3326730)
            local oi=component(owner_manager,0x18,0x30,ammo_id,ammo_rec)
            if not oi or r.u(r.read(r.p(owner_manager+0x38)+oi*4,4),0)~=aid then return nil,'alternate weapon owner mismatch' end
            wid,rec,record_address=ammo_id,ammo_rec,ammo_address
        end
        local driver=global('driver');local di=component(driver,0x28,0x40,wid,rec)
        if not di then return nil,'no weapon driver' end
        local driver_state=r.read(r.p(driver+0x50)+di*40,40)
        local flags=r.u(driver_state,0)
        local result={id=main_wid,unit_ref=r.u(main_rec,16),avatar_unit_ref=unit,resource_hex=string.format('%08x%08x',r.u(main_rec,4),r.u(main_rec,0)),lowered=lowered,alternate=mounted,reloadable=flag(flags,0x40)}
        if wid~=main_wid then result.ammo_resource_hex=string.format('%08x%08x',r.u(rec,4),r.u(rec,0));result.alternate_fire=true end
        -- Diagnostic values only. +0x0C is not yet a verified engine/Lua handle.
        -- All bytes below were already read for ownership and ammo selection.
        result.binding={module_base=base,record=main_address,candidate=r.u(main_rec,12),
            avatar_id=aid,avatar_record=owner+Layout.records+ai*24,avatar_candidate=r.u(avatar,12),driver_state=driver_state}
        local kind=flag(flags,0x80) and 'magazine' or flag(flags,0x100) and 'rounds' or flag(flags,0x200) and 'heat'
        if kind then
            local m=global(kind);local mag=kind=='magazine'
            local i=component(m,mag and 0x20 or 0x28,mag and 0x38 or 0x40,wid,rec)
            if not i then return nil,'ammo component missing' end
            local cfg=config(kind,m,wid,rec,owner);result.kind=kind
            if kind=='heat' then
                local rt=r.read(r.p(m+0x58)+i*12,12)
                if not cfg then return nil,'heat calibration missing' end
                local limit=r.f(cfg,0x60);local heat=r.f(rt,4)
                assert(limit>0 and limit<1e7 and heat>=-1 and heat<1e7,'heat range')
                result.heat=math.max(0,math.min(1,heat/limit));result.locked=rt:byte(9)==1
                local sinks=r.i(rt,0)
                if valid(sinks,1000) and r.u(cfg,0x5c)>0 then result.reserve=sinks;result.reserve_kind='SINKS' end
            else
                local st=r.read(r.p(m+(mag and 0x48 or 0x50))+i*(mag and 16 or 24),mag and 16 or 24)
                local rt=r.read(r.p(m+(mag and 0x50 or 0x58))+i*(mag and 12 or 20),mag and 12 or 20)
                result.binding.ammo_state=st
                result.binding.ammo_runtime=rt
                result.binding.driver_flags=flags
                local sel=mag and 0 or r.u(rt,4);assert(sel<=1,'magazine selection')
                result.ammo_slot=sel
                if not mag and cfg then
                    result.projectile_type=r.u(cfg,0x40+sel*4)
                    result.binding.ammo_types=cfg:sub(0x40+1,0x48)
                end
                local chambered=cfg and cfg:byte((mag and 0x9c or 0x68)+1)==1
                local chamber=chambered and r.u(st,mag and 8 or 16)>0 and 1 or 0
                result.rounds=r.i(st,mag and 0 or 4+sel*4)+chamber
                result.chamber_rounds=chamber
                result.chamber_supported=chambered==true
                assert(valid(result.rounds,5001),'ammo range')
                if cfg then
                    local capacity=mag and r.u(cfg,0x88) or r.f(cfg,0x48+sel*4)
                    if valid(capacity,5000) and capacity>=1 then result.capacity=capacity end
                    -- A full replacement magazine reserves its chamber round before
                    -- the bolt animation completes. Observed runtime +8 clears on chambering.
                    if mag and chambered and chamber==0 and result.capacity and
                        result.rounds==result.capacity-1 and rt:byte(9)==1 then
                        result.pending_chamber_round=1
                        result.rounds=result.rounds+1
                    end
                end
                local reserve=r.i(rt,0)
                local reserve_max=cfg and r.u(cfg,mag and 0x94 or 0x50)
                if valid(reserve,100000) and (not reserve_max or reserve_max>0) then
                    result.reserve=reserve;result.reserve_kind=mag and 'MAGS' or 'ROUNDS'
                end
                -- Inventory ownership plus the matching pack resource survives respawns;
                -- adjacent entity IDs alone do not identify an autocannon backpack.
                local autocannon=result.resource_hex=='a8cffb316f0b5c5f'
                if autocannon or (cfg and reserve_max==0 and not mounted) then
                    for off=12,24,4 do
                        local bid=r.u(inventory,off)
                        local matches=not autocannon and bid==wid+1
                        if autocannon and bid~=wid then
                            local pack=entity(owner,bid)
                            matches=pack and string.format('%08x%08x',r.u(pack,4),r.u(pack,0))=='e60ae045e0090f4c'
                        end
                        if matches then
                            local count=deposit(owner,bid)
                            if count~=nil then result.reserve=count;result.reserve_kind='PACK';break end
                        end
                    end
                end
            end
        elseif flag(flags,0x400) then
            result.kind='resource'
            for _,off in ipairs(Layout.resource) do
                local ok,count=pcall(function()
                    local m=r.p(base+off);local i=component(m,0x20,0x38,wid,rec)
                    if not i then return nil end
                    local provider=r.u(r.read(r.p(m+0x48)+i*36,36),0)
                    return deposit(owner,provider)
                end)
                if ok and count then result.rounds=count;break end
            end
            if not result.rounds then return nil,'resource provider unavailable' end
        else return nil,'unsupported ammo component' end
        do
            -- Optional mode metadata must not suppress otherwise valid ammunition.
            local ok,mode,fire_mode=pcall(function()
                assert(r.read(base+0x75673a,7)==string.char(0x4c,0x8b,0x15,0x9f,0x05,0xbd,0x02),'ammo control getter binding')
                local manager=r.p(base+0x3326ce0)
                local index=component(manager,0x30,0x48,main_wid,main_rec)
                if not index then return nil end
                local count=r.u(r.read(manager+0x20,4),0)
                assert(count<=4096 and index<count,'ammo control bounds')
                local controls=r.read(r.p(manager+0x60)+index*12,12)
                assert(r.read(main_address,24)==main_rec,'ammo control weapon changed')
                local mode=result.resource_hex=='a8cffb316f0b5c5f' and HUD.ammo_types.autocannon_mode(r.u(controls,4)) or nil
                local settings=config('weapon_data',manager,main_wid,main_rec,owner)
                local choices=settings and {r.u(settings,0x90),r.u(settings,0x94),r.u(settings,0x98)}
                local fire_mode=result.alternate_fire and 'ALT' or HUD.ammo_types.selectable_fire_mode(r.u(controls,0),choices)
                return mode,fire_mode
            end)
            if ok then result.ammo_mode=mode;result.fire_mode=fire_mode end
        end
        if control_address then assert(r.u(r.read(control_address,4),0)==active_mode,'fire mode changed during snapshot') end
        self.status='ok';return HUD.ammo_types.apply(result)
    end
    function self.poll()
        local ok,value,reason=pcall(self.snapshot)
        if not ok then self.status=tostring(value);return nil end
        self.status=reason or 'ok';return value
    end
    return self
end
return M

end)()
HUD.pose=(function()
-- Read-only selected-weapon root pose. Native code is inspected, never invoked.
-- See WEAPON_BINDING.md. Unknown implementations or recycled handles fail closed.
local M={}
local function unhex(s) return (s:gsub('..',function(h)return string.char(tonumber(h,16))end)) end
local pose_prefix=unhex('40534883ec204863da')
local pose_suffix=unhex('488bc84c8b0041ff90e8000000488bcb48c1e10648034828488bc14883c4205bc3')
local resolver_prefix=unhex('48895c24084889742410574883ec20488b35')
local resolver_body=unhex('8bc325ffff3f003b8698000000720433dbeb1c8bc8488b86a0000000c1eb16381c0175eb488b8688000000488b1cc8')
function M.new(backend)
    local r=HUD.memory.new(backend)
    local self={status='not sampled',samples=0}
    function self.snapshot(raw,research,anchor_hash)
        assert(raw and raw.binding,'no weapon binding')
        local b=raw.binding;r.reset()
        -- The reader must validate the game build before returning this binding.
        local api=r.p(b.module_base+0x3326308);local unit_api=r.p(api+0x18)
        local getter=r.p(unit_api+0x90);local code=r.read(getter,48)
        assert(code:sub(1,9)==pose_prefix and code:byte(10)==0xe8 and code:sub(15,47)==pose_suffix,'unknown pose getter')
        local resolver=getter+14+r.i(code,10);code=r.read(resolver,116)
        assert(code:sub(1,18)==resolver_prefix and code:sub(0x26,0x54)==resolver_body,'unknown unit resolver')
        local registry=r.p(resolver+0x16+r.i(code,0x12))
        local cap=r.u(r.read(registry+0x98,4),0);assert(cap>0 and cap<=0x400000,'unit capacity')
        local index=b.candidate%0x400000;local generation=math.floor(b.candidate/0x400000)%256
        assert(index>0 and index<cap,'unit index')
        local array=r.p(registry+0x88);local generations=r.p(registry+0xa0)
        assert(r.read(generations+index,1):byte()==generation,'recycled unit')
        local object=r.p(array+index*8)
        assert(r.u(r.read(object+8,4),0)==b.candidate,'unit identity')
        local accessor=r.p(r.p(object)+0xe8)
        assert(r.read(accessor,5)==unhex('488d4160c3'),'unknown scene accessor')
        local nodes=r.u(r.read(object+0x70,4),0);assert(nodes>0 and nodes<=4096,'node count')
        local address=r.p(object+0x88);local bytes=r.read(address,64);local matrix={}
        for i=1,16 do matrix[i]=r.f(bytes,(i-1)*4) end
        for _,i in ipairs({4,8,12}) do assert(math.abs(matrix[i])<1e-5,'matrix affine row') end
        assert(math.abs(matrix[16]-1)<1e-5,'matrix homogeneous component')
        for _,k in ipairs({1,5,9}) do
            local norm=0;for j=0,2 do norm=norm+matrix[k+j]^2 end
            assert(math.abs(norm-1)<.05,'matrix axis scale')
        end
        for _,pair in ipairs({{1,5},{1,9},{5,9}}) do
            local dot=0;for j=0,2 do dot=dot+matrix[pair[1]+j]*matrix[pair[2]+j] end
            assert(math.abs(dot)<.05,'matrix axes')
        end
        for i=13,15 do assert(math.abs(matrix[i])<1e7,'matrix position') end
        local sight
        -- Optional named anchor; any unavailable or changing table keeps root fallback.
        local sight_ok,sight_value=pcall(function()
            assert(nodes<=128,'sight node limit')
            local hashes=r.p(object+0xa0);local data=r.read(hashes,nodes*4)
            for n=0,nodes-1 do
                if r.u(data,n*4)==(anchor_hash or 0x527c9c73) then
                    local pose=r.read(address+n*64,64);local delta={}
                    for j=1,3 do delta[j]=r.f(pose,(11+j)*4)-matrix[12+j];assert(math.abs(delta[j])<5,'sight bounds') end
                    assert(r.p(object+0xa0)==hashes and r.read(hashes,nodes*4)==data,'sight table changed')
                    local result={index=n}
                    for axis,k in ipairs({1,5,9}) do
                        local v=0;for j=1,3 do v=v+delta[j]*matrix[k+j-1] end
                        result[({'x','y','z'})[axis]]=v
                    end
                    return result
                end
            end
        end)
        if sight_ok then sight=sight_value end
        local node_parts
        if research then
            assert(nodes<=128,'research node limit')
            node_parts={{name='weapon_identity',address=b.record,data=r.read(b.record,24)},{name='weapon_scene_header',address=object+0x60,data=r.read(object+0x60,128)}}
            -- Native node lookup (+0x6d8) uses scene+0x40; parent lookup
            -- (+0x500) uses scene+0x38. Scene accessor returns object+0x60.
            local node_hashes=r.p(object+0xa0);local parents=r.p(object+0x98)
            node_parts[#node_parts+1]={name='weapon_scene_node_hashes',address=node_hashes,data=r.read(node_hashes,nodes*4)}
            node_parts[#node_parts+1]={name='weapon_scene_parents',address=parents,data=r.read(parents,nodes*4)}
            assert(r.p(object+0xa0)==node_hashes and r.p(object+0x98)==parents and r.u(r.read(object+0x70,4),0)==nodes,'scene tables changed')
            local scene_resource=r.p(object+0x68)
            node_parts[#node_parts+1]={name='weapon_scene_resource',address=scene_resource,data=r.read(scene_resource,512)}
            for first=0,nodes-1,64 do
                local at=address+first*64
                node_parts[#node_parts+1]={name='weapon_nodes_'..first,address=at,data=r.read(at,math.min(64,nodes-first)*64)}
            end
            if research~='avatar' then
            local resource_getter=r.p(r.p(object)+0x1b0)
            local resource_code=r.read(resource_getter,64)
            node_parts[#node_parts+1]={name='weapon_resource_accessor',address=resource_getter,data=resource_code}
            assert(resource_code:sub(1,8)==unhex('488b8178010000c3'),'unknown weapon resource accessor')
            local resource=r.p(object+0x178);local names=r.p(resource+0x28)
            local header=r.read(names,32);local count=r.u(header,0x14);local offset=r.u(header,0x18)
            node_parts[#node_parts+1]={name='weapon_resource_header',address=resource,data=r.read(resource,256)}
            node_parts[#node_parts+1]={name='weapon_lookup_table_header',address=names,data=header}
            assert(count<=128 and offset<0x100000,'lookup table bounds')
            if count>0 then node_parts[#node_parts+1]={name='weapon_lookup_hashes',address=names+offset,data=r.read(names+offset,count*4)} end
            assert(r.p(object+0x178)==resource and r.p(resource+0x28)==names,'weapon resource changed')
            node_parts[#node_parts+1]={name='weapon_object_header',address=object,data=r.read(object,96)}
            if research=='api' then
                for off=0x4f8,0x700,8 do
                    local ok,entry=pcall(function()local fn=r.p(unit_api+off);return {name=string.format('weapon_api_%x',off),address=fn,data=r.read(fn,128)} end)
                    if ok then node_parts[#node_parts+1]=entry end
                end
            end
            local lookup=r.p(unit_api+0x3b0)
            node_parts[#node_parts+1]={name='weapon_node_lookup_code',address=lookup,data=r.read(lookup,512)}
            end
        end
        -- Revalidate both ends after the read; no persistent entity/matrix pointer cache.
        local record=r.read(b.record,24)
        assert(r.u(record,8)==raw.id and r.u(record,12)==b.candidate and r.u(record,16)==raw.unit_ref,'weapon changed')
        assert(r.read(generations+index,1):byte()==generation and r.p(array+index*8)==object,'unit recycled during read')
        assert(r.u(r.read(object+8,4),0)==b.candidate and r.p(object+0x88)==address,'pose owner changed')
        return {id=raw.id,resource_hex=raw.resource_hex,candidate=b.candidate,node_count=nodes,
            node_parts=node_parts,sight=sight,matrix=matrix,x=matrix[13],y=matrix[14],z=matrix[15]}
    end
    function self.poll(raw)
        local ok,value=pcall(self.snapshot,raw)
        if not ok then self.status=tostring(value);return nil end
        self.status='verified root pose';self.samples=self.samples+1;return value
    end

    return self
end
return M

end)()
HUD.camera_mode=(function()
-- Read the game's accepted first-person toggle, never physical key presses.
-- The native toggle resolves the local player and changes one byte at +0x2EC.
local M={}
local signatures={{0xa42a74,'4c8b0ded398e02'},{0xa42b1f,'4138bc24ec020000'},{0xa42b2a,'41888424ec020000'}}
function M.read(backend,raw)
    local ok,value=pcall(function()
        assert(raw and raw.binding,'no current weapon identity')
        local r=HUD.memory.new(backend);r.reset()
        local base=raw.binding.module_base
        for _,s in ipairs(signatures) do
            local expected=s[2]:gsub('..',function(h)return string.char(tonumber(h,16))end)
            assert(r.read(base+s[1],#expected)==expected,'unknown first-person control binding')
        end
        local player=r.p(base+HUD.layouts.player)
        assert(r.u(r.read(player+0x3a8,4),0)==raw.avatar_unit_ref,'avatar changed')
        local local_record=r.p(player+0xe8);local local_data=r.read(local_record,24)
        assert(local_data:byte(21)%2==1 and r.map(player+0xd0,r.u(local_data,8),64)==0,'not local player slot')
        local flag=r.read(player+0x2ec,1):byte()
        assert(flag==0 or flag==1,'invalid first-person state')
        assert(r.p(base+HUD.layouts.player)==player and r.p(player+0xe8)==local_record and
            r.u(r.read(player+0x3a8,4),0)==raw.avatar_unit_ref,'avatar changed during mode read')
        return flag==1
    end)
    if ok then return value,'game first-person state' end
    return nil,tostring(value)
end
-- Observed active shoulder state, read through the native character flag owner.
function M.read_shoulder(backend,raw,aiming)
    local ok,value=pcall(function()
        assert(raw and raw.binding,'no current weapon identity')
        local r=HUD.memory.new(backend);r.reset()
        local base=raw.binding.module_base
        for _,s in ipairs({{0xa4604c,'4c8b15cd0c8e02'},{0xa460da,'4869c138120000'},{0xa460e1,'4a8b841088e8530048c1e82a2401'}}) do
            local expected=s[2]:gsub('..',function(h)return string.char(tonumber(h,16))end)
            assert(r.read(base+s[1],#expected)==expected,'unknown shoulder control binding')
        end
        local player=r.p(base+HUD.layouts.player)
        assert(r.u(r.read(player+0x3a8,4),0)==raw.avatar_unit_ref,'avatar changed')
        local manager=r.p(base+0x3326d20)
        local index=r.map(manager+0xf8,raw.binding.avatar_id,65536)
        assert(index and index<16,'no bounded shoulder slot')
        local identity=r.p(manager+0x110+index*8)
        assert(identity==raw.binding.avatar_record,'shoulder avatar identity mismatch')
        local flag=r.read(manager+0x53e88d+index*0x1238,1):byte()
        local aim
        if aiming then
            local flags=r.read(manager+0x53e880+index*0x1238,16)
            aim=math.floor(flags:byte(11)/4)%2==1
            assert(aim==(math.floor(flags:byte(16)/32)%2==1),'aiming flags disagree')
            assert(r.read(manager+0x53e880+index*0x1238,16)==flags,'aiming flags changed')
        end
        assert(r.p(base+0x3326d20)==manager and r.p(manager+0x110+index*8)==identity and
            r.p(base+HUD.layouts.player)==player and r.u(r.read(player+0x3a8,4),0)==raw.avatar_unit_ref,'shoulder owner changed')
        if aiming then return aim end
        return math.floor(flag/4)%2==1
    end)
    if ok then return value,'game shoulder state' end
    return nil,tostring(value)
end
function M.read_aiming(backend,raw) return M.read_shoulder(backend,raw,true) end
return M

end)()
HUD.projection=(function()
-- Diagnostic world-to-screen projection. Reads data only; no engine calls.
-- Initial scope: perspective camera with identity local camera offset.
local M={}
local function unhex(s)return (s:gsub('..',function(h)return string.char(tonumber(h,16))end))end
function M.project(m,x,y,z,fov,aspect,near)
    assert(fov>.05 and fov<3.1 and aspect>.1 and aspect<10,'projection dimensions')
    for i=1,16 do assert(type(m[i])=='number' and m[i]==m[i] and math.abs(m[i])<1e7,'camera matrix finite') end
    for _,k in ipairs({1,5,9}) do
        local n=m[k]^2+m[k+1]^2+m[k+2]^2;assert(math.abs(n-1)<.01,'camera axis scale')
    end
    for _,p in ipairs({{1,5},{1,9},{5,9}}) do
        local a,b=p[1],p[2];assert(math.abs(m[a]*m[b]+m[a+1]*m[b+1]+m[a+2]*m[b+2])<.01,'camera axes')
    end
    assert(math.abs(m[4])+math.abs(m[8])+math.abs(m[12])+math.abs(m[16]-1)<1e-5,'camera affine')
    local dx,dy,dz=x-m[13],y-m[14],z-m[15]
    local right=dx*m[1]+dy*m[2]+dz*m[3]
    local depth=dx*m[5]+dy*m[6]+dz*m[7]
    local up=dx*m[9]+dy*m[10]+dz*m[11]
    if depth<=math.max(near,.05) then return nil,'behind camera or near plane' end
    local t=math.tan(fov*.5)
    local nx,ny=.5+.5*right/(depth*t*aspect),.5+.5*up/(depth*t)
    if nx~=nx or ny~=ny or nx<0 or nx>1 or ny<0 or ny>1 then return nil,'outside viewport' end
    return {x=nx,y=ny,depth=depth},'projected weapon root'
end
-- Screen-relative seed only; this does not establish model clearance.
function M.auto_mount(camera,p,fov,aspect,near)
    local dx,dy,dz=p.x-camera[13],p.y-camera[14],p.z-camera[15]
    local depth=dx*camera[5]+dy*camera[6]+dz*camera[7]
    depth=math.max(near+.15,math.max(.55,depth))
    local nx=(p.first_person or p.left_shoulder) and .42 or .58
    local right=(nx-.5)*2*depth*math.tan(fov*.5)*aspect
    local up=-.04*depth*math.tan(fov*.5)
    local x=camera[13]+camera[5]*depth+camera[1]*right+camera[9]*up-p.x
    local y=camera[14]+camera[6]*depth+camera[2]*right+camera[10]*up-p.y
    local z=camera[15]+camera[7]*depth+camera[3]*right+camera[11]*up-p.z
    local m=p.matrix
    return {x=x*m[1]+y*m[2]+z*m[3],y=x*m[5]+y*m[6]+z*m[7],z=x*m[9]+y*m[10]+z*m[11]}
end
function M.left_shoulder(previous,lateral,first_person)
    if first_person or not lateral then return false end
    return lateral>(previous and 0.4 or 0.7)
end
function M.first_person(previous,distance,fov)
    if not distance or not fov then return false end
    if previous then return distance<0.95 and fov<1.45 end
    return distance<0.75 and fov<1.3
end
function M.new(backend)
    local r=HUD.memory.new(backend);local self={status='not sampled'}
    function self.snapshot(base,pose,aspect)
        r.reset()
        local api=r.p(base+0x3326308);local camera_api=r.p(api+0x20)
        local getter=r.p(camera_api+0xf8)
        assert(r.read(getter,10)==unhex('48895c2408574883ec60'),'unknown projection wrapper')
        local call=r.read(getter+0x132,5);assert(call:byte()==0xe8,'unknown projection call')
        local impl=getter+0x137+r.i(call,1)
        assert(r.read(impl,16)==unhex('488bc448895808488968104889701857'),'unknown projection implementation')
        assert(r.read(impl+0x62,20)==unhex('488b471848c1e206418be948035028e80a951500'),'unknown camera scene layout')
        local state=r.p(base+0x346d560);local camera=r.p(state);local b=r.read(camera,160)
        local scene=r.p(camera+0x18);local index=r.u(b,0x20)
        assert(index<4096,'camera node index')
        assert(r.u(b,0x30)==1 and r.u(b,0x50)==0,'unsupported camera projection mode')
        local near,fov=r.f(b,0x28),r.f(b,0x34)
        assert(near>0 and near<10,'camera near plane')
        -- Nonidentity local offsets require a separately verified inverse transform.
        for _,o in ipairs({0x80,0x84,0x88,0x90,0x94,0x98,0x48,0x4c}) do
            assert(math.abs(r.f(b,o))<1e-6,'camera local offset unsupported')
        end
        assert(math.abs(math.abs(r.f(b,0x8c))-1)<1e-6,'camera local rotation unsupported')
        local array=r.p(scene+0x28);local data=r.read(array+index*64,64);local matrix={}
        for i=1,16 do matrix[i]=r.f(data,(i-1)*4) end
        assert(r.p(base+0x346d560)==state and r.p(state)==camera and r.p(camera+0x18)==scene
            and r.u(r.read(camera+0x20,4),0)==index and r.p(scene+0x28)==array,'camera changed during read')
        self.camera_matrix=matrix;self.camera_near=near;self.camera_aspect=aspect
        self.camera_distance=math.sqrt((pose.x-matrix[13])^2+(pose.y-matrix[14])^2+(pose.z-matrix[15])^2)
        self.camera_fov=fov
        self.camera_lateral=(pose.x-matrix[13])*matrix[1]+(pose.y-matrix[14])*matrix[2]+(pose.z-matrix[15])*matrix[3]
        return M.project(matrix,pose.x,pose.y,pose.z,fov,aspect,near)
    end
    function self.poll(base,pose,aspect)
        if not base or not pose then self.status='no weapon pose';return nil end
        self.camera_matrix=nil;self.camera_near=nil;self.camera_aspect=nil
        self.camera_distance=nil;self.camera_fov=nil;self.camera_lateral=nil
        local ok,result,status=pcall(self.snapshot,base,pose,aspect)
        self.status=ok and status or tostring(result)
        return ok and result or nil
    end
    return self
end
return M

end)()
HUD.anchor=(function()
-- Read the native crosshair controller AFTER the game's update.
-- Layout independently traced from hud_crosshair -> native update -> screen XY.
-- Never invokes game functions or writes game memory.
local M={}
local SPEC={
    manager=0x346D538,camera=0x346D560,hud=0x24E340,crosshair=0x19AAF8,
    signatures={
        {0x12F53AF,'488b2d82811702'},
        {0x12F588F,'488d8d40e32400448bc60f28cee8af63ffffeb17'},
        {0x12EBDF4,'498d8ef8aa1900448bc30f28cfe85aa74c00'},
        {0x17B6718,'488b0521fcb6018b8830c50a00'},
        {0x17B6FF5,'f20f1008488b4424500f28c1f3410f118f88200000f30f5cce0fc6c055f3410f11878c200000'},
        {0x17B7050,'f30f594010498bcf8b542424f30f114583488b44245849898790200000'},
        {0x144C370,'488b81f00000004885c074130f1f4000488bc8488b80f00000004885c075f1488bc1c3'}
    }
}
M.spec=SPEC
function M.new(backend)
    local r=HUD.memory.new(backend)
    local base,validated,failed;local self={status='not sampled',samples=0}
    local function validate()
        r.reset();base=assert(backend.module('game.dll'),'game.dll not loaded')
        local d=r.read(base,64);assert(d:sub(1,2)=='MZ','DOS signature')
        local offset=r.u(d,0x3c);assert(offset<0x100000,'PE offset')
        local h=r.read(base+offset,0x80)
        assert(h:sub(1,4)=='PE\0\0' and HUD.layouts.stamps[r.u(h,8)]==r.u(h,0x50),'unsupported anchor build')
        for _,s in ipairs(SPEC.signatures) do
            local expected=s[2]:gsub('..',function(hex)return string.char(tonumber(hex,16))end)
            assert(r.read(base+s[1],#expected)==expected,string.format('anchor signature %X',s[1]))
        end
        validated=true
    end
    local function optional_pointer(a)
        local b=r.read(a,8);local p=r.u(b,0)+r.u(b,4)*2^32
        if p==0 then return nil end
        assert(p>=65536 and p<2^47,'anchor pointer');return p
    end
    local function snapshot()
        r.reset()
        local manager=r.p(base+SPEC.manager)
        local hud=manager+SPEC.hud
        if r.read(hud+0x58,1):byte(1)==0 or r.read(hud+0x21f5b0,1):byte(1)==0 then return nil,'native HUD inactive' end
        local control=hud+SPEC.crosshair
        local b=r.read(control+0x2080,24)
        local state=r.u(b,0)
        if state==1 then return nil,'native reticle hidden' end
        assert(state>=2 and state<=4,'invalid reticle state')
        local pixel_x,pixel_y=r.f(b,8),r.f(b,12)
        local dx,dy=r.f(b,16),r.f(b,20)
        -- This is the same bounded parent walk as native UI root lookup 144C370.
        local root=control;local visited={};local finished=false
        for _=1,32 do
            assert(not visited[root],'UI parent cycle');visited[root]=true
            local parent=optional_pointer(root+0xf0)
            if not parent then finished=true;break end
            root=parent
        end
        assert(finished,'UI parent depth')
        local size=r.read(root+0xc,8);local width,height=r.f(size,0),r.f(size,4)
        assert(width>=64 and width<=32768 and height>=64 and height<=32768,'UI root dimensions')
        local camera=r.p(base+SPEC.camera);local offset=r.read(camera+0xdc,8)
        local cx,cy=r.f(offset,0),r.f(offset,4)
        assert(math.abs(cx)<=1 and math.abs(cy)<=1,'camera screen offset')
        -- Native: local = (screen - 0.5*viewport*(1+camera_offset))/viewport * UI_size.
        -- Invert it to normalize without confusing render-scale pixels with output pixels.
        local nx,ny=0.5*(1+cx)+dx/width,0.5*(1+cy)+dy/height
        assert(nx>=-1 and nx<=2 and ny>=-1 and ny<=2,'reticle coordinates out of range')
        assert(math.abs(pixel_x)<=65536 and math.abs(pixel_y)<=65536,'screen position out of range')
        assert(r.p(base+SPEC.manager)==manager and r.u(r.read(control+0x2080,4),0)==state,'reticle changed during read')
        self.samples=self.samples+1;self.native_state=state
        self.pixel_x,self.pixel_y,self.dx,self.dy=pixel_x,pixel_y,dx,dy
        self.min_x=math.min(self.min_x or nx,nx);self.max_x=math.max(self.max_x or nx,nx)
        self.min_y=math.min(self.min_y or ny,ny);self.max_y=math.max(self.max_y or ny,ny)
        return {x=math.max(0,math.min(1,nx)),y=math.max(0,math.min(1,1-ny)),visible=true},'native crosshair'
    end
    function self.poll()
        if failed then return nil end
        if not validated then
            local ok,err=pcall(validate)
            if not ok then self.status=tostring(err);failed=not self.status:find('game.dll not loaded',1,true);return nil end
        end
        local ok,result,status=pcall(snapshot)
        self.status=ok and status or tostring(result)
        return ok and result or nil
    end
    return self
end
return M

end)()
HUD.view=(function()
local M={}
function M.new(sr)
    local gui,world;local ids={};local G,W,A=sr.Gui,sr.World,sr.Application
    local font='core/performance_hud/debug'
    local self={}
    local blur;local probe_frames=0
    local candidates={'content/ui/shared/material/gui_blur','content/ui/shared/material/blur_background'}
    local function live(w)
        for _,v in pairs(A.worlds() or {}) do if v==w then return true end end
        return false
    end
    function self.clear()
        if gui and live(world) then
            for _,v in ipairs(ids) do pcall(G['destroy_'..v.type],gui,v.id) end
        end
        ids={}
    end
    function self.release()
        if gui and live(world) then self.clear();W.destroy_gui(world,gui) end
        gui,world,ids=nil,nil,{};blur=nil;probe_frames=0
    end
    local function ensure()
        if gui and not live(world) then gui,world,ids=nil,nil,{};blur=nil;probe_frames=0 end
        if not gui then
            local main=A.main_world()
            for _,v in pairs(A.worlds() or {}) do if v~=main then world=v;break end end
            world=world or main;if not world then return end
            gui=W.create_screen_gui(world,'scale',1,1)
        end
        return gui~=nil
    end
    function self.draw(commands)
        if not ensure() then return end
        self.clear()
        if not blur and probe_frames%120==0 and type(A.can_get)=='function' and type(G.bitmap)=='function' then
            for _,name in ipairs(candidates) do
                local ok,available=pcall(A.can_get,'material',name)
                if ok and available then blur=name;break end
            end
        end
        probe_frames=probe_frames+1
        for _,c in ipairs(commands) do
            local color=sr.Color(math.floor(c.a*255+0.5),c.c[1],c.c[2],c.c[3])
            local id
            local kind=c.type
            if c.type=='panel' then
                local drawn=false
                if c.frosted and blur then
                    local ok,bid=pcall(G.bitmap,gui,blur,sr.Vector3(c.x,c.y,48),sr.Vector2(c.w,c.h),sr.Color(255,255,255,255))
                    if ok and bid then ids[#ids+1]={type='bitmap',id=bid};drawn=true
                    else blur=nil;probe_frames=1 end
                end
                self.material_status=drawn and ('native frost: '..blur) or 'opaque panel (native frost unavailable or disabled)'
                -- No fake translucent fallback when the game's blur resource is unavailable.
                if not drawn then color=sr.Color(255,c.c[1],c.c[2],c.c[3]) end
                id=G.rect(gui,sr.Vector3(c.x,c.y,49),sr.Vector2(c.w,c.h),color);kind='rect'
            elseif c.type=='rect' then
                id=G.rect(gui,sr.Vector3(c.x,c.y,50),sr.Vector2(c.w,c.h),color)
            else
                local resource,material=HUD.native_font.resolve(sr,c.font,false)
                if resource then id=G.text(gui,c.text,resource,c.size,material,sr.Vector3(c.x,c.y,51),color) end

            end
            if id then ids[#ids+1]={type=kind,id=id} end
        end
    end
    return self
end
return M

end)()
HUD.pose_motion=(function()
-- Frame-rate independent rigid-pose smoothing; no engine userdata retained.
local M={}
local function quaternion(m)
    local a,b,c=m[1],m[6],m[11];local x,y,z,w;local t=a+b+c
    if t>0 then
        local s=math.sqrt(t+1)*2;w=s/4;x=(m[7]-m[10])/s;y=(m[9]-m[3])/s;z=(m[2]-m[5])/s
    elseif a>b and a>c then
        local s=math.sqrt(1+a-b-c)*2;w=(m[7]-m[10])/s;x=s/4;y=(m[5]+m[2])/s;z=(m[9]+m[3])/s
    elseif b>c then
        local s=math.sqrt(1+b-a-c)*2;w=(m[9]-m[3])/s;x=(m[5]+m[2])/s;y=s/4;z=(m[10]+m[7])/s
    else
        local s=math.sqrt(1+c-a-b)*2;w=(m[2]-m[5])/s;x=(m[9]+m[3])/s;y=(m[10]+m[7])/s;z=s/4
    end
    local n=math.sqrt(x*x+y*y+z*z+w*w);return {x/n,y/n,z/n,w/n}
end
local function blend(a,b,t)
    local dot=0;for i=1,4 do dot=dot+a[i]*b[i]end
    local sign=dot<0 and -1 or 1;dot=math.min(1,math.abs(dot))
    local u,v=1-t,t
    if dot<.9995 then local angle=math.acos(dot);local den=math.sin(angle);u=math.sin((1-t)*angle)/den;v=math.sin(t*angle)/den end
    local q={};local n=0;for i=1,4 do q[i]=a[i]*u+b[i]*sign*v;n=n+q[i]^2 end
    n=math.sqrt(n);for i=1,4 do q[i]=q[i]/n end;return q
end
-- Preserve forward direction while aligning the panel's up axis with world up.
function M.upright(m)
    local fx,fy,fz=m[5],m[6],m[7]
    local n=math.sqrt(fx*fx+fy*fy)
    if n<.05 then return m end -- Near vertical aim has no stable horizontal right.
    local rx,ry=fy/n,-fx/n
    return {rx,ry,0,0,fx,fy,fz,0,ry*fz,-rx*fz,rx*fy-ry*fx,0,m[13],m[14],m[15],1}
end
function M.step(s,m,x,y,z,key,dt,c)
    dt=type(dt)=='number' and dt==dt and dt>=0 and dt or 1/60
    local q=quaternion(m)
    local jump=s.x and (s.x-x)^2+(s.y-y)^2+(s.z-z)^2>4
    if not s.q or s.key~=key or dt>.35 or jump then
        s.x,s.y,s.z,s.q=x,y,z,q
    else
        local a=c.world_position_smooth==0 and 1 or 1-math.exp(-dt/c.world_position_smooth)
        s.x,s.y,s.z=s.x+(x-s.x)*a,s.y+(y-s.y)*a,s.z+(z-s.z)*a
        local dx,dy,dz=s.x-x,s.y-y,s.z-z;local d=math.sqrt(dx*dx+dy*dy+dz*dz)
        if d>c.world_max_lag then local k=c.world_max_lag/d;s.x,s.y,s.z=x+dx*k,y+dy*k,z+dz*k end
        local t=c.world_rotation_smooth==0 and 1 or 1-math.exp(-dt/c.world_rotation_smooth)
        s.q=blend(s.q,q,t)
    end
    s.key=key
    local a,b,c,d=s.q[1],s.q[2],s.q[3],s.q[4]
    return {1-2*(b*b+c*c),2*(a*b+c*d),2*(a*c-b*d),0,
        2*(a*b-c*d),1-2*(a*a+c*c),2*(b*c+a*d),0,
        2*(a*c+b*d),2*(b*c-a*d),1-2*(a*a+b*b),0,s.x,s.y,s.z,1}
end
return M

end)()
HUD.world_probe=(function()
-- Minimal world-space GUI experiment; only engine-returned world/GUI handles.
local M={}
function M.new(sr,log,direct)
    local A,W,G=sr.Application,sr.World,sr.Gui
    local smooth={};local depth_fill;local blur;local gui,world;local failed=false;local first=true
    local self={status='not started'}
    local function identity(handle)
        -- LuaJIT %p bypasses the engine's generic '[Material]' __tostring.
        -- This identifies Lua userdata storage, not necessarily its native object.
        local ok,address=pcall(string.format,'%p',handle)
        local native_ok,native=pcall(function()return string.format('0x%X',tonumber(require('ffi').cast('uintptr_t',handle)))end)
        return tostring(handle)..(ok and (' lua_address='..address) or '')..(native_ok and (' native_address='..native) or '')
    end
    local function live(w)
        if not w then return false end
        for _,v in pairs(A.worlds() or {})do if v==w then return true end end
        return false
    end
    function self.release()
        if gui and live(world) then
            log('WORLD_GUI destroy begin');W.destroy_gui(world,gui);log('WORLD_GUI destroy complete')
        end
        gui,world=nil,nil;blur=nil;depth_fill=nil;smooth={}
    end
    local function draw(p,c,commands,dt)
        if (not c.world_probe and not commands) or not p then self.release();return end
        if not W.create_world_gui or not G.move or not sr.Matrix4x4 or not sr.Matrix4x4.from_axes then
            self.status='world GUI functions missing';return
        end
        if gui and not live(world) then gui,world=nil,nil;smooth={} end
        local main=A.main_world()
        if not live(main) then self.status='no live main world';return end
        if gui and main~=world then self.release() end
        local m=p.matrix
        local x,y,z=HUD.scene_test.mount(p,c)
        local px=p.x+m[1]*x+m[5]*y+m[9]*z
        local py=p.y+m[2]*x+m[6]*y+m[10]*z
        local pz=p.z+m[3]*x+m[7]*y+m[11]*z
        if c.placement_mode=='auto' and p.first_person then m=HUD.pose_motion.upright(m) end
        if c.keep_hud_upright then m=HUD.pose_motion.upright(m) end
        m=HUD.pose_motion.step(smooth,m,px,py,pz,tostring(c.placement_mode)..':'..tostring(p.id)..':'..tostring(p.candidate),dt,c)
        px,py,pz=m[13],m[14],m[15]
        if first then log('WORLD_GUI matrix begin') end
        local pose=sr.Matrix4x4.from_axes(sr.Vector3(m[1],m[2],m[3]),
            sr.Vector3(m[5],m[6],m[7]),sr.Vector3(m[9],m[10],m[11]),sr.Vector3(px,py,pz))
        if not gui then
            world=main;log('WORLD_GUI create begin')
            gui=assert(W.create_world_gui(world,pose,1000,1000,'immediate'),'world GUI returned nil')
            log('WORLD_GUI create complete')
            local name='mods/dbf_hud/materials/depth_fill'
            local control='mods/dbf_hud/materials/depth_state_test_loader_control'
            if not direct and A.can_get and A.can_get('material',control) then depth_fill=control
            elseif not direct and A.can_get and A.can_get('material',name) then depth_fill=name
            elseif not direct and A.can_get and A.can_get('material','mods/astra_ammo/materials/depth_fill') then
                depth_fill='mods/astra_ammo/materials/depth_fill' -- Previously deployed optional material.
            end
            log('WORLD_GUI depth material '..(direct and 'not requested' or (depth_fill and 'available' or 'missing; install depth material addon')))
            -- One-time observation only: resolve the same material used by bitmap.
            -- Keep no native material handles across frames or GUI destruction.
            if c.debug_logging then
            log('WORLD_GUI instance '..identity(gui)..' world '..identity(world))
            if type(G.material)=='function' and A.can_get then
                for _,material_name in ipairs({'content/ui/shared/material/gui_fill',
                    depth_fill or 'mods/dbf_hud/materials/depth_fill','mods/dbf_hud/materials/depth_blur'}) do
                    if A.can_get('material',material_name) then
                        local ok,handle=pcall(G.material,gui,material_name)
                        log('WORLD_GUI material instance '..material_name..' '..(ok and identity(handle) or 'lookup failed'))
                    end
                end
            else log('WORLD_GUI material inspection unavailable') end
            end
        else
            if first then log('WORLD_GUI move begin') end
            G.move(gui,pose)
        end
        if commands then
            -- Native screen frost renders white on the verified world-GUI path.
            -- Keep the user's frost preference for screen modes; omit it here.
            -- Bitmap takes the material as a required argument. This avoids relying
            -- on the game's optional rect material overload matching upstream.
            local function solid(x,y,w,h,layer,color)
                if depth_fill then
                    G.bitmap(gui,depth_fill,sr.Vector3(x,y,layer),sr.Vector2(w,h),color)
                else G.rect(gui,sr.Vector3(x,y,layer),sr.Vector2(w,h),color) end
            end
            for _,v in ipairs(commands) do
                local color=sr.Color(math.floor(v.a*255+.5),v.c[1],v.c[2],v.c[3])
                if v.type=='panel' then
                    -- Match the known-working hybrid background; leave experimental
                    -- depth fill on foreground primitives only during this comparison.
                    solid(v.x,v.y,v.w,v.h,1,color)
                elseif v.type=='rect' then
                    solid(v.x,v.y,v.w,v.h,2,color)
                else
                    local resource,material=HUD.native_font.resolve(sr,v.font,c.occlusion_mode~='gui')
                    if resource then G.text(gui,v.text,resource,v.size,material,sr.Vector3(v.x,v.y,3),color) end

                end
            end
            if first then log('WORLD_GUI panel submitted: '..(depth_fill and 'explicit material bitmap path' or 'default rectangle path'));first=false end
            self.status='world panel; frost unavailable on this rendering path';return true
        end
        if first then log('WORLD_GUI rect begin') end
        G.rect(gui,sr.Vector3(0,0,0),sr.Vector2(240,140),sr.Color(255,45,52,55))
        G.rect(gui,sr.Vector3(0,0,1),sr.Vector2(12,140),sr.Color(255,231,200,92))
        if first then log('WORLD_GUI rect complete');first=false end
        self.status='world rectangle submitted'
    end
    function self.draw(p,c,commands,dt)
        if failed then return end
        local ok,err=pcall(draw,p,c,commands,dt)
        if not ok then
            failed=true;self.status=tostring(err);log('WORLD_GUI Lua failure: '..self.status)
            pcall(self.release)
        end
        return ok and err==true
    end
    return self
end
return M


end)()
HUD.offscreen_test=(function()
-- Isolated one-frame render test. Never renders from the update callback.
local M={}
function M.start(sr,log,globals,panel_provider,show_preview)
    globals=globals or _G
    local self={};local active=true;local submitted=false;local first_render=true
    local A,W,R,V,U,G=sr.Application,sr.World,sr.Renderer,sr.Viewport,sr.Unit,sr.Gui
    local world,viewport,target,camera,environment,gui
    local preview,preview_world
    local world_ready=false
    local source_ids={};local elapsed=0
    local texture_w,texture_h=64,64
    local density=panel_provider and 4 or 1
    function self.tick(dt,refresh_hz,scanline_strength)
        elapsed=elapsed+(dt or 0)
        if panel_provider and active and world and gui and (not world_ready or refresh_hz==0 or elapsed>=1/(refresh_hz or 60)) then
            elapsed=0
            local commands=panel_provider()
            if commands then
                local f=commands[1]
                assert(f.w>0 and f.h>0,'invalid panel bounds')
                if math.ceil(f.w*density)~=texture_w or math.ceil(f.h*density)~=texture_h then
                    self.resize_required=true;return
                end
                self.aspect=texture_w/texture_h
                local sx,sy=density,density
                for _,id in ipairs(source_ids) do G.destroy_rect(gui,id) end
                source_ids={}
                local function rect(x,y,w,h,c,a)
                    -- Preserve the selected RGB values; no experimental color transform.
                    local rgb=c
                    local function strip(bottom,height,factor)
                        local id=G.rect(gui,sr.Vector3((x-f.x)*sx,(bottom-f.y)*sy,1),sr.Vector2(w*sx,height*sy),sr.Color(math.floor(255*(a or 1)),math.floor(rgb[1]*factor+0.5),math.floor(rgb[2]*factor+0.5),math.floor(rgb[3]*factor+0.5)))
                        source_ids[#source_ids+1]=id
                    end
                    local strength=scanline_strength or 0
                    if strength<=0 then strip(y,h,1);return end
                    -- One dim row per four source pixels, aligned across all primitives.
                    -- Modulate RGB only: never paint opaque bands into clear texels.
                    local bottom=y
                    while bottom<y+h do
                        local row=math.floor(bottom-f.y+0.000001)
                        local top=math.min(y+h,f.y+row+1)
                        if top<=bottom then break end
                        strip(bottom,top-bottom,row%4==0 and (1-strength) or 1)
                        bottom=top
                    end
                end
                for _,c in ipairs(commands) do
                    if c.type=='text' then
                        -- Archived mesh glyph rendering removed.
                    else rect(c.x,c.y,c.w,c.h,c.c,c.a) end
                end
                world_ready=false;submitted=false
            end
        end
        if active and world and not world_ready then
            world_ready=true
            if type(W.update)=='function' then
                if not panel_provider then log('OFFSCREEN private world update begin') end
                local ok,err=pcall(W.update,world,0)
                if not panel_provider or not ok then log(ok and 'OFFSCREEN private world update complete' or ('OFFSCREEN private world update failed '..tostring(err))) end
                if not ok then active=false end
            else log('OFFSCREEN private world update unavailable') end
        end
    end
    local bridge=rawget(globals,'HUDRenderBridge');local unsubscribe
    function self.release()
        active=false
        if unsubscribe then unsubscribe();unsubscribe=nil end
        local ok=true
        local function destroy(fn,...)
            if not ok then return end
            local done,err=pcall(fn,...);ok=done
            if not done then log('OFFSCREEN cleanup failed '..tostring(err)) end
        end
        if preview then
            local live=false
            for _,w in pairs(A.worlds() or {}) do if w==preview_world then live=true end end
            if live then destroy(W.destroy_gui,preview_world,preview) end
            if ok then preview=nil end
        end
        if gui then destroy(W.destroy_gui,world,gui);if ok then gui=nil end end
        if viewport then destroy(A.destroy_viewport,world,viewport);if ok then viewport=nil end end
        if environment then destroy(W.destroy_shading_environment,world,environment);if ok then environment=nil end end
        if world then destroy(A.release_world,world);if ok then world=nil end end
        if target then destroy(R.destroy_resource,target);if ok then target=nil end end
        if ok then log('OFFSCREEN cleanup complete') end
    end
    if not bridge or bridge.api~=1 or type(bridge.subscribe)~='function' then
        local loader=rawget(globals,'CowboyBingusModLoader')
        local state=loader and loader.modules and loader.modules['mods/holographic_utility_display/render_bridge']
        log('OFFSCREEN blocked: startup HUD render bridge required; loader='..tostring(state)..'; render='..type(rawget(globals,'render')))
        self.waiting_for_bridge=true
        return self
    end
    if panel_provider then
        local commands=panel_provider()
        if not commands then self.waiting_for_panel=true;return self end
        texture_w,texture_h=math.ceil(commands[1].w*density),math.ceil(commands[1].h*density)
        assert(texture_w>0 and texture_h>0 and texture_w<=2048 and texture_h<=2048,'panel texture bounds invalid')
        self.aspect=texture_w/texture_h
    end
    local ok,err=pcall(function()
        for _,pair in ipairs({{A,'new_world'},{A,'release_world'},{A,'create_viewport'},{A,'destroy_viewport'},
            {A,'render_world'},{A,'can_get'},{W,'spawn_unit'},{W,'create_screen_gui'},
            {W,'destroy_gui'},{W,'destroy_shading_environment'},
            {U,'camera'},{R,'create_resource'},{R,'destroy_resource'},{V,'set_output_render_target'},
            {G,'rect'}}) do assert(pair[1] and type(pair[1][pair[2]])=='function','missing '..pair[2]) end
        local name='core/units/camera'
        if not A.can_get('unit',name) then name='core/appkit/units/camera/camera' end
        if not A.can_get('unit',name) then
            for _,ns_name in ipairs({'Camera','World','Application'}) do
                local names={};local ns=sr[ns_name]
                if type(ns)=='table' then for key,value in pairs(ns) do
                    if type(key)=='string' and type(value)=='function' and
                        (ns_name=='Camera' or key:lower():find('camera',1,true)) then names[#names+1]=key end
                end end
                table.sort(names);log('OFFSCREEN CAMERA_API '..ns_name..' '..table.concat(names,' '))
            end
            for _,candidate in ipairs({'core/appkit/units/camera','content/markers/camera_marker',
                'core/editor_slave/stingray_editor/editor_camera'}) do
                log('OFFSCREEN CAMERA_RESOURCE '..candidate..' '..tostring(A.can_get('unit',candidate)))
            end
        end
        assert(A.can_get('unit',name),'camera resource unavailable: '..name)
        local environment_name='core/stingray_renderer/environments/midday/midday'
        local default_environment=type(W.create_default_shading_environment)=='function'
        if not default_environment then
            assert(type(W.create_shading_environment)=='function','missing create_shading_environment')
            assert(A.can_get('shading_environment',environment_name),'default environment resource unavailable')
        end
        log('OFFSCREEN setup begin')
        world=assert(A.new_world())
        local unit=assert(W.spawn_unit(world,name))
        camera=assert(U.camera(unit,1),'camera unavailable')
        environment=assert(default_environment and W.create_default_shading_environment(world)
            or W.create_shading_environment(world,environment_name))
        viewport=assert(A.create_viewport(world,'offscreen_ui_weapon_screen'))
        target=assert(R.create_resource('render_target','R8G8B8A8',texture_w,texture_h))
        V.set_output_render_target(viewport,target)
        self.texture=target
        gui=assert(W.create_screen_gui(world,'scale',1,1))
        if not panel_provider then
        for i,color in ipairs({{230,60,60},{60,210,100},{60,110,230},{230,200,60}}) do
            G.rect(gui,sr.Vector3(((i-1)%2)*32,math.floor((i-1)/2)*32,1),sr.Vector2(32,32),
                sr.Color(255,color[1],color[2],color[3]))
        end
        end
        log(string.format('OFFSCREEN source GUI ready at %dx%d',texture_w,texture_h))
    end)
    if not ok then log('OFFSCREEN setup stopped '..tostring(err));self.release();return self end
    unsubscribe=bridge.subscribe('dbf_hud.offscreen',function(...)
        if active and world_ready and not submitted then
            submitted=true
            if first_render then log('OFFSCREEN render callback entered') end
            local done,why=pcall(A.render_world,world,camera,viewport,environment)
            if first_render or not done then log(done and 'OFFSCREEN render submitted; pixels unverified' or ('OFFSCREEN render failed '..tostring(why))) end
            first_render=false
            if done and show_preview~=false and not preview then
                local shown,reason=pcall(function()
                    log('OFFSCREEN preview preflight begin')
                    assert(type(G.material)=='function','Gui.material unavailable')
                    assert(sr.Material and type(sr.Material.set_resource)=='function','Material.set_resource unavailable')
                    assert(type(G.bitmap)=='function','Gui.bitmap unavailable')
                    assert(type(A.main_world)=='function','Application.main_world unavailable')
                    assert(A.can_get('material','content/ui/shared/material/gui_diffuse_map'),'preview material unavailable')
                    local main=assert(A.main_world())
                    preview_world=main
                    for _,candidate in pairs(A.worlds() or {}) do
                        if candidate~=main and candidate~=world then preview_world=candidate;break end
                    end
                    log('OFFSCREEN preview world '..(preview_world==main and 'main fallback' or 'HUD world'))
                    log('OFFSCREEN preview GUI create begin')
                    preview=assert(W.create_screen_gui(preview_world,'scale',1,1))
                    -- Independent control: visible geometry does not depend on the render target.
                    G.rect(preview,sr.Vector3(896,296,79),sr.Vector2(panel_provider and texture_w/density+8 or 200,panel_provider and texture_h/density+8 or 200),sr.Color(255,255,0,255))
                    G.rect(preview,sr.Vector3(panel_provider and 916+texture_w/density or 1104,300,80),sr.Vector2(48,48),sr.Color(255,255,255,255))
                    for i,color in ipairs({{255,0,0},{255,255,0},{0,255,0},{0,0,255},{128,128,128},{255,255,255}}) do
                        G.rect(preview,sr.Vector3(900+(i-1)*32,260,81),sr.Vector2(32,24),sr.Color(255,color[1],color[2],color[3]))
                    end
                    log('OFFSCREEN color comparison reference enabled')
                    log('OFFSCREEN preview material lookup begin')
                    for _,candidate in ipairs({'core/performance_hud/gui','content/ui/shared/material/gui_diffuse_map','content/ui/shared/material/gui_fill','content/ui/shared/material/gui_white_alpha'}) do
                        if A.can_get('material',candidate) then
                            local valid,result=pcall(function()
                                local ffi=require('ffi')
                                return string.format('0x%X',tonumber(ffi.cast('uintptr_t',G.material(preview,candidate))))
                            end)
                            log('OFFSCREEN material candidate '..candidate..' '..(valid and result or 'lookup failed'))
                        else log('OFFSCREEN material candidate '..candidate..' unavailable') end
                    end
                    local material=assert(G.material(preview,'content/ui/shared/material/gui_diffuse_map'))
                    log('OFFSCREEN material Lua type='..type(material)..'; target Lua type='..type(target))
                    local pointer_ok,pointers=pcall(function()
                        local ffi=require('ffi')
                        local mp=tonumber(ffi.cast('uintptr_t',material))
                        local tp=tonumber(ffi.cast('uintptr_t',target))
                        assert(mp and mp>=65536,'Gui.material returned a null or invalid native pointer')
                        assert(tp and tp>=65536,'render target returned a null or invalid native pointer')
                        return string.format('material=0x%X target=0x%X',mp,tp)
                    end)
                    assert(pointer_ok,pointers)
                    log('OFFSCREEN native pointer check '..pointers)
                    -- Native signature and diffuse_map slot verified; null handles rejected above.
                    log('OFFSCREEN verified texture binding begin')
                    sr.Material.set_resource(material,'diffuse_map',target)
                    log('OFFSCREEN preview bitmap draw begin')
                    G.bitmap(preview,'content/ui/shared/material/gui_diffuse_map',sr.Vector3(900,300,80),sr.Vector2(panel_provider and texture_w/density or 192,panel_provider and texture_h/density or 192),sr.Color(255,255,255,255))
                    log('OFFSCREEN four-color preview placed above/right of native bottom-left HUD')
                end)
                if not shown then log('OFFSCREEN preview stopped '..tostring(reason)) end
            end
        end
    end)
    log('OFFSCREEN waiting for render callback')
    return self
end
return M

end)()
HUD.world_style=(function()
-- Pure WorldGUI geometry scaling, frame fitting and visual presets.
local M={}
function M.prepare(commands,p,c)
                    local f=commands[1];local scale=240*(c.scale or 1)/f.w
                    if c.placement_mode=='auto' and p.first_person then scale=scale*.5 end;local centered={}
                    for _,command in ipairs(commands) do
                        local v={};for k,value in pairs(command) do v[k]=value end
                        v.x=(v.x-f.x-f.w/2)*scale;v.y=(v.y-f.y-f.h/2)*scale
                        if v.w then v.w=v.w*scale end
                        if v.h then v.h=v.h*scale end
                        if v.size then v.size=v.size*scale end
                        centered[#centered+1]=v
                    end
                    -- Pixel glyphs quantize after world scaling; fit their actual bounds.
                    if HUD.font.supported(c.font) then
                        local panel=centered[1]
                        local left,bottom,right,top=panel.x,panel.y,panel.x+panel.w,panel.y+panel.h
                        local padding=math.max(1,8*2*(c.scale or 1)*scale)
                        for _,v in ipairs(centered) do
                            if v.type=='text' and not v.child then
                                local a,b,e,f=HUD.font.measure(v.text,v.size,v.font,true)
                                left=math.min(left,v.x+a-padding);bottom=math.min(bottom,v.y+b-padding)
                                right=math.max(right,v.x+e+padding);top=math.max(top,v.y+f+padding)
                            end
                        end
                        for _,v in ipairs(centered) do
                            if v.decoration and not v.child then
                                v.x=left+(v.x-panel.x)*(right-left)/panel.w
                                v.y=bottom+(v.y-panel.y)*(top-bottom)/panel.h
                                v.w=v.w*(right-left)/panel.w
                                v.h=v.h*(top-bottom)/panel.h
                            end
                        end
                        panel.x,panel.y,panel.w,panel.h=left,bottom,right-left,top-bottom
                    end
                    -- World glyph scaling and frame fitting may change the final
                    -- bounds after screen-layout centering. Align actual glyphs here.
                    local panel=centered[1];local middle=panel.x+panel.w/2
                    local bar_left,bar_right=math.huge,-math.huge
                    for _,v in ipairs(centered) do
                        if v.center_in_frame then
                            local a,b,e,f
                            if HUD.font.supported(v.font) then a,b,e,f=HUD.font.measure(v.text,v.size,v.font,true) end
                            if not e then a,e=0,#v.text*v.size*.6 end
                            v.x=middle-(a+e)/2
                        elseif v.center_bar then
                            bar_left=math.min(bar_left,v.x);bar_right=math.max(bar_right,v.x+v.w)
                        end
                    end
                    if bar_left<math.huge then
                        local shift=middle-(bar_left+bar_right)/2
                        for _,v in ipairs(centered) do if v.center_bar then v.x=v.x+shift end end
                    end
                    local heading;local icon_left,icon_right=math.huge,-math.huge
                    for _,v in ipairs(centered) do
                        if v.mode_count then heading=v end
                        if v.mode_icon then icon_left=math.min(icon_left,v.x);icon_right=math.max(icon_right,v.x+v.w) end
                    end
                    if heading and icon_left<math.huge then
                        local a,b,e,f
                        if HUD.font.supported(heading.font) then a,b,e,f=HUD.font.measure(heading.text,heading.size,heading.font,true) end
                        if not e then a,e=0,#heading.text*heading.size*.6 end
                        local gap=8*scale;local width=e-a+gap+icon_right-icon_left
                        local start=middle-width/2;heading.x=start-a
                        local shift=start+e-a+gap-icon_left
                        for _,v in ipairs(centered) do if v.mode_icon then v.x=v.x+shift end end
                    end
                    local child_panel,child_text
                    for _,v in ipairs(centered) do
                        if v.child and v.type=='panel' then child_panel=v end
                        if v.child and v.type=='text' then child_text=v end
                    end
                    if child_panel and child_text then
                        local old={x=child_panel.x,y=child_panel.y,w=child_panel.w,h=child_panel.h}
                        local a,b,e,f
                        if HUD.font.supported(child_text.font) then a,b,e,f=HUD.font.measure(child_text.text,child_text.size,child_text.font,true) end
                        if not e then a,b,e,f=0,-child_text.size*.2,#child_text.text*child_text.size*.6,child_text.size*.8 end
                        local pad=4*2*(c.scale or 1)*scale
                        local width,height=panel.w,f-b+2*pad
                        child_panel.x=middle-width/2;child_panel.y=panel.y-2*2*(c.scale or 1)*scale-height
                        child_panel.w,child_panel.h=width,height
                        child_text.x=middle-(a+e)/2;child_text.y=child_panel.y+pad-b
                        for _,v in ipairs(centered) do
                            if v.child and v.decoration then
                                v.x=child_panel.x+(v.x-old.x)*width/old.w
                                v.y=child_panel.y+(v.y-old.y)*height/old.h
                                v.w=v.w*width/old.w;v.h=v.h*height/old.h
                            end
                        end
                    end
                    if c.style_3d=='hologram' then
                        local panel=centered[1];local clock=c.style_clock or 0
                        local flicker=.96+.025*math.sin(clock*17)+.015*math.sin(clock*31)
                        for _,v in ipairs(centered) do v.a=v.a*flicker end
                        panel.a=panel.a*.18
                        if child_panel then child_panel.a=child_panel.a*.18 end
                        local ink=HUD.config.rgb(c.text_color)
                        local strength=commands[2] and commands[2].a or 1
                        for _,frame in ipairs(child_panel and {panel,child_panel} or {panel}) do
                            local thickness=math.max(.3,frame.w/500)
                            for _,edge in ipairs({{frame.x,frame.y,frame.w,thickness},{frame.x,frame.y+frame.h-thickness,frame.w,thickness}}) do
                                centered[#centered+1]={type='rect',x=edge[1],y=edge[2],w=edge[3],h=edge[4],c=ink,a=.18*strength}
                            end
                            centered[#centered+1]={type='rect',x=frame.x,y=frame.y+(clock*.35%1)*(frame.h-thickness),w=frame.w,h=thickness,c=ink,a=.10*strength}
                        end
                    end
    return centered
end
return M

end)()
HUD.archived_mesh=(function()
-- Archived mesh carrier. Production uses direct WorldGUI.
local M={}
function M.new(sr,log,side)
    local A,W,U,Mesh=sr.Application,sr.World,sr.Unit,sr.Mesh
    local unit,world,bound,scene_material,last_emission,screen_test;local failed=false;local smooth={}
    local self={}
    local function live(w)
        for _,v in pairs(A.worlds() or {}) do if w==v then return true end end
        return false
    end
    function self.release()
        if unit and live(world) then W.destroy_unit(world,unit) end
        unit,world,bound,scene_material,last_emission=nil,nil,nil,nil,nil;smooth={}
    end
    function self.draw(p,c,target,dt,aspect)
        if failed then return end
        if not p or not target then if unit then self.release() end;return end
        local ok,err=pcall(function()
            local main=A.main_world()
            if not live(main) then return end
            if unit and (world~=main or not live(world)) then self.release() end
            if unit and screen_test~=(c.weapon_screen_test==true) then self.release() end
            if not unit then
                local name='content/art_shared/meshes/plane_primitive'
                assert(A.can_get('unit',name),'plane unit unavailable')
                for _,fn in ipairs({'set_local_pose','set_local_scale','num_meshes','mesh'}) do assert(type(U[fn])=='function','missing Unit.'..fn) end
                assert(Mesh and type(Mesh.num_materials)=='function' and type(Mesh.material)=='function','mesh material API unavailable')
                world=main
                for _,candidate in ipairs({'mods/dbf_hud/materials/fullbright_depth_image','core/appkit/materials/loading_screen','content/effects/base_shaders/mesh_particle_simple','content/env_ship/hangar/props/materials/store_screen_large','content/fac_helldivers/equipment/primary_weapons/assault_rifle_nacho/materials/weapon_screen'}) do
                    log('SCENE fullbright candidate '..candidate..' loaded='..tostring(A.can_get('material',candidate)))
                end
                log('SCENE plane spawn begin')
                unit=assert(W.spawn_unit(world,name))
                assert(U.num_meshes(unit)==1,'unexpected mesh count')
                if type(U.set_mesh_visibility)=='function' then
                    log('SCENE shadow-only visibility begin side='..side)
                    U.set_mesh_visibility(unit,1,false,'shadow_caster')
                    log('SCENE shadow-only visibility returned side='..side)
                end
                local mesh=U.mesh(unit,1)
                assert(Mesh.num_materials(mesh)==1,'unexpected material count')
                local transparent='content/art_shared/materials/placeholder_red_transparent'
                screen_test=c.weapon_screen_test==true
                if screen_test then transparent='content/fac_helldivers/equipment/primary_weapons/assault_rifle_nacho/materials/weapon_screen' end
                local alpha=type(U.set_material)=='function' and A.can_get('material',transparent)
                if screen_test then assert(alpha,'weapon screen material unavailable') end
                if alpha then
                    -- Unit asset declares the named slot 'material' (thin hash eac0b497).
                    log('SCENE transparent material assignment begin')
                    U.set_material(unit,'material',transparent)
                end
                local material=Mesh.material(mesh,1)
                local ffi=require('ffi')
                assert(tonumber(ffi.cast('uintptr_t',material))>=65536,'invalid scene material')
                assert(tonumber(ffi.cast('uintptr_t',target))>=65536,'invalid panel texture')
                log('SCENE verified material texture bind begin')
                if screen_test then
                    sr.Material.set_resource(material,'input_image',target)
                    sr.Material.set_scalar(material,'screen_enabled',1)
                    sr.Material.set_vector4(material,'screen_rect',sr.Vector4(side==-1 and 1 or 0,0,side==-1 and -1 or 1,1))
                    sr.Material.set_vector2(material,'Atlas_size',sr.Vector2(1,1))
                    sr.Material.set_vector2(material,'resolution_multiplier',sr.Vector2(1,1))
                    for _,name in ipairs({'normal_map_amount','normal_map_coloring_amount','dirt_amount','distortion_amount','artifacts_amount','light_bleed_amount','use_dropshadow'}) do
                        sr.Material.set_scalar(material,name,0)
                    end
                    log('SCENE weapon screen image bound side='..side..'; appearance unverified')
                else
                sr.Material.set_resource(material,'color_map',target)
                sr.Material.set_resource(material,'emissive_map',target)
                sr.Material.set_scalar(material,'use_color_map',1)
                sr.Material.set_scalar(material,'use_emissive_map',1)
                if side==-1 then
                    sr.Material.set_vector2(material,'uv_scale',sr.Vector2(-1,1))
                    sr.Material.set_vector2(material,'uv_offset',sr.Vector2(1,0))
                end
                scene_material=material
                sr.Material.set_vector3(material,'base_color',sr.Vector3(0,0,0))
                -- Diagnostic: black metallic base removes the dielectric reflection term.
                sr.Material.set_scalar(material,'use_metallic_map',0)
                sr.Material.set_scalar(material,'metallic',1)
                sr.Material.set_scalar(material,'use_roughness_map',0)
                sr.Material.set_scalar(material,'roughness',1)
                sr.Material.set_vector3(material,'emissive',sr.Vector3(1,1,1))
                if alpha then
                    sr.Material.set_scalar(material,'opacity',1)
                    sr.Material.set_scalar(material,'use_opacity_map',1)
                    log('SCENE transparent material bound; alpha pixels unverified')
                end
                end
                scene_material=material
                bound=target
                log('SCENE plane texture bound')
            end
            assert(bound==target,'render target changed without scene retirement')
            if last_emission~=c.emissive_intensity then
                sr.Material.set_scalar(scene_material,screen_test and 'emissive_amount' or 'emissive_intensity',c.emissive_intensity)
                last_emission=c.emissive_intensity
            end
            local m=p.matrix
            local x,y,z=HUD.scene_test.mount(p,c)
            local px=p.x+m[1]*x+m[5]*y+m[9]*z
            local py=p.y+m[2]*x+m[6]*y+m[10]*z
            local pz=p.z+m[3]*x+m[7]*y+m[11]*z
            m=HUD.pose_motion.step(smooth,m,px,py,pz,tostring(p.id)..':'..tostring(p.candidate),dt,c)
            local pose=sr.Matrix4x4.from_axes(sr.Vector3(side*m[1],side*m[2],side*m[3]),sr.Vector3(m[9],m[10],m[11]),sr.Vector3(-side*m[5],-side*m[6],-side*m[7]),sr.Vector3(m[13],m[14],m[15]))
            U.set_local_pose(unit,1,pose)
            U.set_local_scale(unit,1,sr.Vector3(0.24,0.24/math.max(0.25,math.min(8,aspect or 2)),0.24))
        end)
        if not ok then failed=true;log('SCENE stopped '..tostring(err));self.release() end
    end
    return self
end
function M.fullbright(sr,log)
    local gui,world,bound;local stopped=false;local smooth={}
    local A,W,G=sr.Application,sr.World,sr.Gui
    local self={}
    function self.release()
        if gui then
            for _,w in pairs(A.worlds() or {}) do if w==world then W.destroy_gui(world,gui);break end end
        end
        gui,world,bound=nil,nil,nil;smooth={}
    end
    function self.draw(p,c,target,dt,aspect)
        if stopped or not G or not W.create_world_gui then return end
        if not p or not target then self.release();return end
        local ok,err=pcall(function()
            local main=A.main_world()
            if gui and world~=main then self.release() end
            local name='mods/dbf_hud/materials/fullbright_depth_image'
            if not A.can_get('material',name) then return end
            local x,y,z=HUD.scene_test.mount(p,c)
            local m=p.matrix
            local px=p.x+m[1]*x+m[5]*y+m[9]*z
            local py=p.y+m[2]*x+m[6]*y+m[10]*z
            local pz=p.z+m[3]*x+m[7]*y+m[11]*z
            m=HUD.pose_motion.step(smooth,m,px,py,pz,tostring(p.id)..':'..tostring(p.candidate),dt,c)
            local pose=sr.Matrix4x4.from_axes(sr.Vector3(m[1],m[2],m[3]),sr.Vector3(m[5],m[6],m[7]),sr.Vector3(m[9],m[10],m[11]),sr.Vector3(m[13],m[14],m[15]))
            if not gui then
                world=main
                log('FULLBRIGHT main-world GUI create begin')
                gui=assert(W.create_world_gui(world,pose,1000,1000,'immediate'))
                local material=G.material(gui,name)
                local ffi=require('ffi')
                assert(tonumber(ffi.cast('uintptr_t',material))>=65536,'null fullbright material')
                assert(tonumber(ffi.cast('uintptr_t',target))>=65536,'null fullbright target')
                sr.Material.set_resource(material,'diffuse_map',target)
                bound=target
                log('FULLBRIGHT image material bound')
            else G.move(gui,pose) end
            assert(bound==target,'fullbright target changed without cleanup')
            G.bitmap(gui,name,sr.Vector3(-120,-120/(aspect or 2),0),sr.Vector2(240,240/(aspect or 2)),sr.Color(255,255,255,255))
        end)
        if not ok then stopped=true;log('FULLBRIGHT stopped '..tostring(err));pcall(self.release) end
    end
    return self
end
return M

end)()
HUD.scene_test=(function()
-- WorldGUI display selection; archived mesh access remains for research.
local M={}
function M.mount(p,c)
    if c.placement_mode=='auto' and p.auto_mount then return p.auto_mount.x,p.auto_mount.y,p.auto_mount.z end
    if p.first_person then return c.fp_mount_x,c.fp_mount_y,c.fp_mount_z+.2 end
    if p.left_shoulder then return c.left_mount_x,c.left_mount_y,c.left_mount_z+.2 end
    return c.mount_x,c.mount_y,c.mount_z+.2
end
function M.new(sr,log,side)
    if not side then
        local front,back=M.new(sr,log,1),M.new(sr,log,-1)
        local overlay=HUD.world_probe.new(sr,log,true)
        local depth_overlay=HUD.world_probe.new(sr,log,false)
        local active_mode
        return {
            draw=function(p,c,target,dt,aspect,commands)
                local mode=c.occlusion_mode or (c.hud_occlusion~=false and 'gui_depth' or 'gui')
                if mode=='mesh' then mode='gui_depth' end -- archived selection
                if active_mode~=mode then
                    front.release();back.release();overlay.release();depth_overlay.release()
                    active_mode=mode
                    log('HUD occlusion mode '..mode)
                end
                do
                    if not commands then overlay.release();depth_overlay.release();return end
                    local centered=HUD.world_style.prepare(commands,p,c)
                    if mode=='gui_depth' then return depth_overlay.draw(p,c,centered,dt) else return overlay.draw(p,c,centered,dt) end
                end
            end,
            release=function() overlay.release();depth_overlay.release();front.release();back.release();active_mode=nil end
        }
    end
    return HUD.archived_mesh.new(sr,log,side)
end
function M.fullbright(sr,log)return HUD.archived_mesh.fullbright(sr,log)end
return M

end)()
HUD.placement=(function()
-- Weapon/view placement. Native readers remain in pose and camera_mode.
-- Sight anchors update live; only the legacy root fallback caches a screen seed.
local M={}
function M.update(self,pose,projection,latest_raw,log)
    if self.weapon_pose then
        self.weapon_pose.first_person=self.first_person
        self.weapon_pose.left_shoulder=false
        self.weapon_pose.auto_mount=nil
        self.weapon_pose.camera_facing=nil
        if self.config.placement_mode=='auto' then
            local equip=tostring(self.weapon_pose.id)..':'..tostring(self.weapon_pose.candidate)..':'..tostring(latest_raw.avatar_unit_ref)
            if self.auto_equip~=equip then self.auto_equip=equip;self.auto_mounts={};self.auto_view=nil end
            local view=self.first_person and 'first' or 'right'
            if self.auto_view~=view then self.auto_view=view;self.auto_sample_after=self.clock+.4 end
            local mount=self.auto_mounts[view]
            local sight=self.weapon_pose.sight
            if sight then
                -- Named anchors need neither camera settling nor cached screen seeds.
                if self.first_person then
                    mount={x=sight.x+(self.config.fp_auto_side=='right' and .12 or -.12),y=sight.y+.45,z=sight.z+.01}
                else
                    mount={x=sight.x+.16,y=sight.y+.10,z=sight.z+.04}
                end
            elseif not mount and projection.camera_matrix and self.clock>=self.auto_sample_after then
                mount=HUD.projection.auto_mount(projection.camera_matrix,self.weapon_pose,
                    projection.camera_fov,projection.camera_aspect,projection.camera_near)
                -- Keep the seed close to the gun; no model-clearance claim yet.
                mount.x=math.max(-.8,math.min(.8,mount.x))
                mount.y=math.max(-.15,math.min(.4,mount.y))
                mount.z=math.max(-.2,math.min(.4,mount.z))
                local side=self.first_person and -1 or 1
                mount.x=side*math.max(.13,math.min(.18,math.abs(mount.x)+.05))
                mount.y=math.max(-.05,math.min(.10,mount.y*.4))
                mount.z=math.max(.03,math.min(.10,mount.z*.4))
                if self.first_person then mount.x=-.12;mount.y=.35;mount.z=.22 end
                self.auto_mounts[view]=mount
            end
            local profile=self.weapon_clearance[self.weapon_pose.resource_hex]
            local profile_view=self.first_person and ('first_'..self.config.fp_auto_side) or view
            local correction=profile and profile[profile_view]
            if mount and correction then
                mount={x=mount.x+(correction.x or 0),y=mount.y+(correction.y or 0),z=mount.z+(correction.z or 0)}
            end
            self.weapon_pose.auto_mount=mount
        else
            self.auto_equip=nil;self.auto_mounts=nil
        end
    end
end
return M

end)()
HUD.weapon_offsets=(function()
-- External weapon profile loading and validation, independent of rendering.
local M={}
function M.load(backend,log)
    local profiles_loaded
    profiles_loaded=HUD.config.weapon_clearance
    if backend.read_weapon_offsets then
        local ok,profiles=pcall(function()
            local values=backend.read_weapon_offsets();if not values then return nil end
            assert(type(values)=='table','weapon offsets must return a table')
            for resource,views in pairs(values) do
                assert(type(resource)=='string' and #resource==16 and resource:match('^%x+$'),'invalid weapon resource')
                assert(type(views)=='table','weapon views must be a table')
                for view,offset in pairs(views) do
                    assert(view=='right' or view=='left' or view=='first_left' or view=='first_right','invalid weapon view')
                    assert(type(offset)=='table','weapon offset must be a table')
                    for axis,value in pairs(offset) do
                        assert(axis=='x' or axis=='y' or axis=='z','invalid offset axis')
                        assert(type(value)=='number' and value==value and math.abs(value)<=2,'offset must be within two metres')
                    end
                end
            end
            return values
        end)
        if ok and profiles then profiles_loaded=profiles end
        if not ok then log('WEAPON_OFFSETS rejected: '..tostring(profiles)) end
    end
    return profiles_loaded
end
return M

end)()
HUD.menu=(function()
-- ModOptionsMenu API 1; only main settings and placement are exposed.
local M={}
function M.new(hud)
    local api,attempted,retired,routes;local self={status='Mod Options Menu not installed'}
    local placement={keep_hud_upright=true,fp_auto_side=true,placement_mode=true,left_mount_x=true,left_mount_y=true,left_mount_z=true,fp_mount_x=true,fp_mount_y=true,fp_mount_z=true,
        mount_x=true,mount_y=true,mount_z=true,world_position_smooth=true,world_rotation_smooth=true,world_max_lag=true,
        weapon_offset_x=true,weapon_offset_y=true,weapon_settle=true,weapon_lag=true,offset_x=true,offset_y=true,
        follow=true,travel=true,settle=true}
    local function option_id(k)if k=='font' then return 'dbf_hud_v5.font_native' end;return (placement[k] and 'dbf_hud_placement.' or 'dbf_hud_v4.')..k end
    local font_choices={}
    for i,name in ipairs(HUD.config.fonts) do font_choices[i]=({bigblue='BigBlue Terminal',hack='Hack',jetbrainsmono='JetBrains Mono',firacode='Fira Code',iosevka='Iosevka'})[name] end
    local function font_index()for i,name in ipairs(HUD.config.fonts) do if name==hud.config.font then return i end end;return 1 end
    local function decoration_index()for i,name in ipairs(HUD.config.decorations) do if name==hud.config.decoration then return i end end;return 1 end
    local sliders={
        {'world_position_smooth','3D position damping',0,0.5,0.005},{'world_rotation_smooth','3D rotation damping',0,0.5,0.005},{'world_max_lag','3D maximum position lag',0,0.5,0.01},
        {'weapon_offset_x','2D hybrid: horizontal offset',-1920,1920,1},{'weapon_offset_y','2D hybrid: vertical offset',-1080,1080,1},
        {'weapon_settle','2D hybrid: settling time',0.04,1,0.01},{'weapon_lag','2D hybrid: maximum lag',0,160,1},
        {'offset_x','2D crosshair: horizontal offset',-1920,1920,1},{'offset_y','2D crosshair: vertical offset',-1080,1080,1},
        {'follow','2D crosshair: reticle follow',0,1,0.01},{'travel','2D crosshair: maximum travel',1,160,1},{'settle','2D crosshair: settling time',0.04,1,0.01},
        {'scale','HUD scale',0.5,2,0.05},{'opacity','HUD opacity',0.1,1,0.01},{'panel_opacity','Panel tint',0,1,0.01},{'flash_hz','Heat warning pulse rate',0.5,3,0.5}}
    -- Mesh-only emission, texture cap and CRT sliders are intentionally archived.
    -- Their configuration and implementations remain in source for future work.
    local function set(k,v) assert(api.set(option_id(k),v)) end
    function self.sync()
        if not api or not attempted or retired then return end
        for _,s in ipairs(sliders) do set(s[1],hud.config[s[1]]) end
        set('display_mode',hud.config.anchor_mode=='weapon' and 1 or (hud.config.anchor_mode=='world' and 3 or 2))
        set('fp_auto_side',hud.config.fp_auto_side=='right' and 2 or 1)
        set('keep_hud_upright',hud.config.keep_hud_upright)
        set('fade_3d_unless_aiming',hud.config.fade_3d_unless_aiming)
        set('style_3d',hud.config.style_3d=='hologram' and 2 or 1)
        set('frosted',hud.config.frosted)
        set('decoration',decoration_index())
        set('debug_logging',hud.config.debug_logging)
        local selected=font_index()
        for page=1,math.ceil(#font_choices/16) do
            local first=(page-1)*16+1
            set(page==1 and 'font' or ('font_page_'..page),selected>=first and selected<first+16 and selected-first+1 or 1)
        end
    end
    function self.poll()
        if attempted or retired then return end
        api=rawget(_G,'ModOptionsMenu')
        if not api or api.api~=1 then return end
        for _,k in ipairs({'register_option','on_change','set'}) do if type(api[k])~='function' then return end end
        attempted=true;api.dbf_hud_routes=api.dbf_hud_routes or {};routes=api.dbf_hud_routes
        -- Old rows may remain visible until restart, but cannot apply stale settings.
        for id,route in pairs(routes) do
            if not id:find('dbf_hud_v4.',1,true) and not id:find('dbf_hud_placement.',1,true) then route.callback=nil;route.owner=nil end
        end
        if routes['dbf_hud_v4.always_visible'] then routes['dbf_hud_v4.always_visible'].callback=nil end
        for id,route in pairs(routes) do if id=='dbf_hud_v4.font_nerd' or id:find('dbf_hud_v4.font_page_',1,true) then route.callback=nil end end
        if routes['dbf_hud_v4.show_3d'] then routes['dbf_hud_v4.show_3d'].callback=nil end
        if routes['dbf_hud_v4.always_show_3d'] then routes['dbf_hud_v4.always_show_3d'].callback=nil end
        local function add(k,spec,callback)
            spec.mod=placement[k] and 'DBF-HUD Placement' or 'DBF-HUD'
            local id=option_id(k)
            local exists=routes[id] or (type(api.get)=='function' and api.get(id)~=nil)
            if not exists then local ok,err=api.register_option(id,spec);assert(ok,err) end
            if not routes[id] then
                local route={};routes[id]=route
                assert(api.on_change(id,function(v)if route.callback then route.callback(v) end end))
            end
            routes[id].owner=self;routes[id].callback=callback
        end
        local ok,err=pcall(function()
            add('display_mode',{type='choice',label='Display mode',choices={'2D, Anchor to Weapon (Hybrid)','2D, Anchor to HUD/Crosshair','3D, WorldGUI'},
                default=hud.config.anchor_mode=='weapon' and 1 or (hud.config.anchor_mode=='world' and 3 or 2)},function(v)
                hud.configure({anchor_mode=v==1 and 'weapon' or (v==3 and 'world' or 'crosshair')});hud.save_tuning()
            end)
            add('keep_hud_upright',{type='toggle',label='Keep HUD upright',default=hud.config.keep_hud_upright,description='Remove sideways roll in every 3D view while preserving facing direction.'},function(v)
                hud.configure({keep_hud_upright=v});hud.save_tuning()
            end)
            add('fp_auto_side',{type='choice',label='Auto first-person HUD side',choices={'Left','Right'},default=hud.config.fp_auto_side=='right' and 2 or 1},function(v)
                hud.configure({fp_auto_side=v==2 and 'right' or 'left'});hud.save_tuning()
            end)
            for _,s in ipairs(sliders) do
                local k=s[1];add(k,{type='slider',label=s[2],min=s[3],max=s[4],step=s[5],default=hud.config[k]},function(v)
                    hud.configure({[k]=v});hud.save_tuning()
                end)
            end
            add('decoration',{type='choice',label='Decorations',choices={'None','Thin outline','Corner brackets','Helldivers HUD','Double frame'},default=decoration_index()},function(v)
                hud.configure({decoration=assert(HUD.config.decorations[v])});hud.save_tuning()
            end)
            -- ModOptionsMenu accepts at most sixteen names per choice.
            for page=1,math.ceil(#font_choices/16) do
                local first=(page-1)*16+1
                local choices={}
                for i=first,math.min(first+15,#font_choices) do choices[#choices+1]=font_choices[i] end
                local key=page==1 and 'font' or ('font_page_'..page)
                local selected=font_index()
                add(key,{type='choice',label='HUD font',choices=choices,
                    default=selected>=first and selected<first+16 and selected-first+1 or 1,
                    description='Choose a font from any group. Only the most recently chosen font is active.'},function(v)
                    hud.configure({font=assert(HUD.config.fonts[first+v-1])});hud.save_tuning()
                end)
            end
            add('fade_3d_unless_aiming',{type='toggle',label='Fade 3D HUD when not aiming',default=hud.config.fade_3d_unless_aiming},function(v)
                hud.configure({fade_3d_unless_aiming=v});hud.save_tuning()
            end)
            add('style_3d',{type='choice',label='3D HUD style',choices={'Standard','Hologram'},default=hud.config.style_3d=='hologram' and 2 or 1},function(v)
                hud.configure({style_3d=v==2 and 'hologram' or 'standard'});hud.save_tuning()
            end)
            add('frosted',{type='toggle',label='Frosted background (2D)',default=hud.config.frosted},function(v)
                hud.configure({frosted=v});hud.save_tuning()
            end)
            add('debug_logging',{type='toggle',label='Debug logging',default=hud.config.debug_logging,
                description='Enable research traces and capability inspection. Errors are always logged.'},function(v)
                hud.configure({debug_logging=v});hud.save_tuning()
            end)
            self.sync()
        end)
        self.status=ok and 'Options > Mods > DBF-HUD' or ('menu unavailable: '..tostring(err));if not ok then api=nil end
    end
    function self.retire()
        retired=true
        for _,route in pairs(routes or {}) do if route.owner==self then route.callback=nil;route.owner=nil end end
    end
    return self
end
return M

end)()
HUD.runtime=(function()
local M={}
function M.start(sr,backend,options)
    local managed=options and options.managed==true
    -- Compatibility: retire a previous-brand instance during live upgrade.
    local legacy=rawget(_G,'AstraAmmo');if legacy and legacy.retire then legacy.retire() end
    local old=rawget(_G,'DBFHUD');if old and old.retire then old.retire() end
    local self={version='0.3.41',status='starting',anchor_status='starting native anchor',clock=0,hidden=false}
    self.config=HUD.config.new()
    local attached=HUD.motion.new();local attachment_active=false
    local motion=HUD.motion.new();local reader=HUD.reader.new(backend);local view=HUD.view.new(sr)
    local native=HUD.anchor.new(backend);self.native_anchor=native
    local pose=HUD.pose.new(backend);local next_pose_log=0;local last_pose_status
    local original=rawget(_G,'update');local shutdown=rawget(_G,'shutdown')
    if not managed and type(original)~='function' then self.status='update callback missing';return self end
    local projection=HUD.projection.new(backend);local binding_base;local next_projection_log=0
    local latest_raw;local next_sample=0;local model;local anchor;local anchor_at=-10;local provider;local failures=0
    function self.texture_commands()
        if not model then return nil end
        local cfg={};for k,v in pairs(self.config) do cfg[k]=v end
        cfg.font='bigblue';cfg.frosted=false
        local commands=HUD.layout.compose(model,0,0,2,1,cfg,self.clock)
        return commands
    end
    local retired=false;local cleaned=false;local alpha=0;local last_id;local width,height
    local manual_until=-1;local anchor_source;local next_log=0;local last_log_status
    local last_binding
    local function log(line) if backend.log then pcall(backend.log,string.format('[%.3f] %s',self.clock,line)) end end
    local function research_log(line)
        if self.config.debug_logging or line:find('failure',1,true) or line:find('missing',1,true) or line:find('stopped',1,true) then log(line) end
    end
    local world_probe=HUD.world_probe.new(sr,research_log)
    local world_display=HUD.scene_test.new(sr,research_log)
    log('START DBFHUD '..self.version..' native crosshair enabled; movement visibility filter removed')
    local function research_snapshot()
    if not self.config.debug_logging then return end
    -- Availability check only: never invokes unverified world GUI functions.
    local capabilities={}
    for _,entry in ipairs({{'World','create_world_gui'},{'World','destroy_gui'},
        {'Gui','move'},{'Gui','rect'},{'Gui','bitmap'},
        {'Matrix4x4','from_axes'},{'Matrix4x4','from_quaternion_position'},
        {'Matrix4x4','identity'},{'Matrix4x4','set_translation'},
        {'Matrix4x4','set_x'},{'Matrix4x4','set_y'},{'Matrix4x4','set_z'}}) do
        local namespace=sr[entry[1]]
        local ok,value=pcall(function()return namespace and namespace[entry[2]]end)
        capabilities[#capabilities+1]=entry[1]..'.'..entry[2]..'='..(ok and type(value) or 'unavailable')
    end
    log('WORLD_GUI_CAPABILITIES '..table.concat(capabilities,' '))
    -- Inspect C binding entry points without invoking the bindings themselves.
    local jit_ok,jit_util=pcall(require,'jit.util')
    for _,entry in ipairs({{'World','create_world_gui'},{'Gui','move'},{'Unit','set_mesh_visibility'},{'Viewport','set_output_render_target'},
        {'Viewport','register_render_resource'},{'Application','create_viewport'},
        {'Application','render_world'},{'Renderer','update_texture_base64'},
        {'Mesh','material'},{'Gui','material'},{'Gui','bitmap'},{'Gui','bitmap_3d'},{'Gui','update_bitmap'},{'Material','set_resource'}}) do
        local ok,address=pcall(function()
            assert(jit_ok,'jit.util unavailable')
            local ns=sr[entry[1]];local fn=ns and ns[entry[2]]
            assert(type(fn)=='function','binding unavailable')
            local info=jit_util.funcinfo(fn);assert(type(info.addr)=='number','no native entry')
            return string.format('0x%X',info.addr)
        end)
        log('SCREEN_BINDING '..entry[1]..'.'..entry[2]..' '..(ok and address or 'unavailable'))
    end
    -- Enumerate exposed names rather than guessing the game's custom bindings.
    for _,namespace in ipairs({'Viewport','Renderer','Material','Unit','Gui','World'}) do
        local ok,names=pcall(function()
            local ns=sr[namespace];local found={}
            if type(ns)~='table' then return {'namespace='..type(ns)} end
            for name,value in pairs(ns) do
                if type(name)=='string' and type(value)=='function' and
                    (namespace~='Unit' or name:find('material',1,true) or name:find('mesh',1,true)) then
                    found[#found+1]=name
                end
            end
            table.sort(found);return found
        end)
        log('SCREEN_API_NAMES '..namespace..' '..(ok and table.concat(names,' ') or 'unavailable'))
    end
    -- Lookup only: do not allocate resources or invoke rendering from update.
    local screen_apis={
        Renderer={'create_resource','destroy_resource'},
        Material={'set_resource','set_texture','set_scalar','set_vector4'},
        Application={'create_viewport','destroy_viewport','render_world','new_world','release_world'},
        Viewport={'set_render_targets','set_render_target','set_rect'},
        World={'spawn_unit','destroy_unit','create_screen_gui','destroy_gui'},
        Unit={'material','set_material','set_local_pose','set_local_scale'},
        Gui={'create_material','material','bitmap','bitmap_3d'}
    }
    for namespace,entries in pairs(screen_apis) do
        local result={}
        for _,name in ipairs(entries) do
            local ok,value=pcall(function()local ns=sr[namespace];return ns and ns[name]end)
            result[#result+1]=name..'='..(ok and type(value) or 'unavailable')
        end
        log('SCREEN_CAPABILITIES '..namespace..' '..table.concat(result,' '))
    end
    for _,resource in ipairs({
        {'shader_library_group','core/stingray_renderer/shader_libraries/default_shaders'},
        {'shader_library','mods/dbf_hud/shaders/gui_depth_state_test_loader_control'},
        {'material','mods/dbf_hud/materials/depth_state_test_loader_control'},
        {'unit','content/env_ship/hologram/units/plane'},
        {'unit','content/env_ship/hologram/units/hologram_cylinder'},
        {'material','content/fac_helldivers/equipment/primary_weapons/assault_rifle_nacho/materials/weapon_screen'}
    }) do
        local ok,available=pcall(function()return sr.Application.can_get(resource[1],resource[2])end)
        log('SCREEN_RESOURCE '..resource[1]..' '..resource[2]..' '..(ok and tostring(available) or 'lookup unavailable'))
    end
    end
    -- Integration contract: normalized viewport coordinates, origin top-left.
    -- Only a verified adapter should supply the actual game's dynamic reticle.
    function self.push_anchor(x,y,visible)
        assert(type(x)=='number' and type(y)=='number' and x==x and y==y and x>=0 and x<=1 and y>=0 and y<=1,'invalid anchor')
        anchor={x=x,y=y,visible=visible~=false};anchor_at=self.clock
        manual_until=self.clock+0.15;anchor_source='external provider'
    end
    function self.set_anchor_provider(fn) assert(fn==nil or type(fn)=='function');provider=fn end
    local menu
    function self.configure(values)
        local was_debug=self.config.debug_logging
        HUD.config.apply(self.config,values);self.config.placement_mode='auto';self.config.show_3d='aiming'
        if self.config.debug_logging and not was_debug then research_snapshot() end
        if menu then menu.sync() end
    end
    function self.export_tuning() return HUD.config.serialize(self.config) end
    function self.save_tuning()
        if not backend.write_tuning then self.tuning_status='file writer unavailable';return false end
        local ok,result=pcall(backend.write_tuning,self.export_tuning())
        self.tuning_status=ok and ('saved '..result) or tostring(result)
        if not ok then log('TUNING '..self.tuning_status) end
        return ok,result
    end
    function self.reload_tuning()
        if not backend.read_tuning then return false end
        local ok,result=pcall(function()local values=backend.read_tuning();if values then self.configure(values) end;return values~=nil end)
        self.tuning_status=ok and (result and 'loaded tuning file' or 'defaults; no tuning file') or tostring(result)
        log('TUNING '..self.tuning_status);return ok and result
    end
    self.reload_tuning()
    self.weapon_clearance=HUD.weapon_offsets.load(backend,log)
    menu=HUD.menu.new(self)
    local next_weapon_screen_lookup=0;local last_weapon_screen_available
    function self.frame(dt)
        if retired then return end
        if type(dt)~='number' or dt~=dt or dt<0 or dt==math.huge then dt=1/60 end
        self.clock=self.clock+dt
        if self.config.debug_logging and self.clock>=next_weapon_screen_lookup then
            next_weapon_screen_lookup=self.clock+5
            local ok,available=pcall(function()
                return sr.Application.can_get('material','content/fac_helldivers/equipment/primary_weapons/assault_rifle_nacho/materials/weapon_screen')
            end)
            local state=ok and tostring(available) or 'lookup unavailable'
            if state~=last_weapon_screen_available then
                log('WEAPON_SCREEN_AVAILABILITY '..state);last_weapon_screen_available=state
            end
        end
        menu.poll();if self.menu_status~=menu.status then log('MENU '..menu.status) end;self.menu_status=menu.status
        if provider then
            local ok,x,y,visible=pcall(provider)
            if ok and x~=nil then local accepted=pcall(self.push_anchor,x,y,visible);if not accepted then self.anchor_status='invalid provider' end end
        end
        if self.clock>=next_sample then
            next_sample=self.clock+1/30
            local raw=reader.poll();latest_raw=raw;binding_base=raw and raw.binding and raw.binding.module_base;model=HUD.model.normalize(raw);self.status=reader.status
            if self.config.debug_logging and self.clock<90 and raw and raw.binding and raw.binding.ammo_state then
